func (d *DoInstance) updateNotifyContext(req *msg.Ds2DoReqMsg) error {
	d.MetricReporter.ReqNotifyMsgFromOcs()
	d.PerfReporter.AddPerfOfReceiveOcsNotifyReq()
	carrier := checkCarrier(req.Session)
	d.ChgContext.Update(req.Session, req.LocalChgSession, context.NotifyProcedure, carrier)
	// 设置接收到的Notify的请求参数
	notifyReqPara, ok := req.Req.GetBody().(*nchf.ChargingDataNotifyParameters)
	if notifyReqPara == nil || !ok {
		return errors.New("get notify req para failed")
	}
	d.GetChgReqParaContext().UpdateNotifyReqPara(notifyReqPara)
	// 设置NotifyUri
	d.NotifyUriBuilder.SetNotifyUriWhenRecvNotifyMsg(req.DestKeyValue)
	return nil
}
func (d *DoInstance) updateChgMsgSession(session *dbadpater.DbSessionInfo, reqFiled *json.ReqField) *dbadpater.DbSessionInfo {
	if session.LocalOcsIpCfgStatus == gconst.OcsIpCfgStatusInitial {
		d.GetLogger().Info("OcsIpCfgStatus is initial, localOcsIpCfg is being Configured")
		session.LocalOcsIpCfgStatus = omcmcfg.LocalOcsIpCfgStatus(d.GetOmcmCfger())
	}

	// 判断是否是NBIOT会话
	d.processNbiotChg(session, reqFiled)

	// 根据MML配置和话单字段判断是否为QBC话单，QBC走离线流程
	d.processQbcChg(session)

	if session.FwdOcsStatus == dbadpater.FwdOcsDisable {
		return session
	}

	// 更新免流标志
	reqHttpCtx := d.GetRecvReqHttpContext()
	d.GetOcsContext().SetFlowFreeScene(reqHttpCtx.RecvReqHuaweiNonSpecSubscriberFreeIndication(),
		reqHttpCtx.RecvReqHuaweiNonSpecSubscriberFreeChargeType(), reqHttpCtx.RecvReqSubHuaweiNonSpecSubscriberFreeIndication())

	d.GetLogger().Info("localOcsIpCfg is (%d). "+
		"0: OcsIpCfgStatusInitial, 1: OcsIpConfigured, 2: OcsIpNotConfigured)", session.LocalOcsIpCfgStatus)
	if session.LocalOcsIpCfgStatus == gconst.OcsIpConfigured {
		session.FwdOcsStatus = dbadpater.FwdOcsEnable
		// 在电信场景下给ChargingStatus赋一个初值，避免在不转发OCS且非异常场景下落单到default通道
		session.ChargingStatus = agf.ChargingStatus_LOCALNORMAL
		// 电信场景判断是否是特殊Dnn
		d.DnnConfig().JudgeIsSpecialDnn(d.GetOmcmCfger(), reqHttpCtx.RecvReqDnnId())
		d.SetCTSpecialDnnChargingStatus(session)
		return session
	}

	// 如果FwdOcsStatus值不是FwdOcsInitial，之前已经查询过，不需要再到OMCM上查询，要判断当前的DNNID是否特殊的DNNID
	switch session.FwdOcsStatus {
	case dbadpater.FwdOcsEnable:
		d.DnnConfig().JudgeIsSpecialDnn(d.GetOmcmCfger(), reqHttpCtx.RecvReqDnnId())
		return session
	case dbadpater.FwdOcsDisable:
		return session
	default:
		d.GetLogger().Info("FwdOcsStatus is FwdOcsInitial, need to query FwdOcsStatus from OMCM by cc")
	}

	return d.updateChgMsgSessionByCCPCCACT(session)
}
func (d *DoInstance) processNbiotChg(session *dbadpater.DbSessionInfo, reqFiled *json.ReqField) {
	if reqFiled != nil && reqFiled.RatType == sbi29571.RatTypeNBIOT {
		// 将会话的 IsNbIotSession 属性设置为 true
		session.IsNbIotSession = true
	}
}
func (d *DoInstance) processQbcChg(session *dbadpater.DbSessionInfo) {
	if d.isQbcChgScene() {
		d.GetLogger().Info("do not forward OCS according to QBC Charging")
		session.FwdOcsStatus = dbadpater.FwdOcsDisable
		// 设置会话为QBC会话
		session.IsQbcSession = true
		d.DoContext.SetQbcScene()
		// 判断漫游话单是否需要单独目录保存
		if d.isQbcScene() {
			d.DoContext.SetQbcIndependDir()
		}
	}
}
func (d *DoInstance) updateChgMsgSessionByCCPCCACT(session *dbadpater.DbSessionInfo) *dbadpater.DbSessionInfo {
	queryResult, err := omcmcfg.MmlCfgCache().Query(d, omcmcfg.NameCcpCcact, session.ChargingCharacter)
	if queryResult == nil || err != nil {
		d.GetLogger().Warning("Query CC config failed: %v:", err)
		session.FwdOcsStatus = dbadpater.FwdOcsDisable
		return session
	}

	// 当在移动场景下，在线CC值的情况下，要判断当前的DNNID是否特殊的DNNID，需要由CHF进行代应答
	if queryResult.(*cm_go.CCPCCACT).FWDOCSENABLE {
		session.FwdOcsStatus = dbadpater.FwdOcsEnable
		d.DnnConfig().JudgeIsSpecialDnn(d.GetOmcmCfger(), d.GetRecvReqHttpContext().RecvReqDnnId())
	} else {
		session.FwdOcsStatus = dbadpater.FwdOcsDisable
	}
	return session
}

