func (c *NetconfClientImpl) execRoutine(cmd string, respCh chan<- respChan) {
	var err error
	var reply *models.RpcReply
	defer close(respCh) // lint !e211
	if c.status == Disconnected {
		nflog.CdrwsLogger().WriteNfLog(nflog.Info, "cdrws: Exec: client %s not connected, reconnect", c.clientId)
		if err = c.reconnect(); err != nil {
			nflog.CdrwsLogger().WriteNfLog(nflog.Error, "cdrws: unable to connect")
			respCh <- respChan{nil, err}
			return
		}
	}
	var resp string
	resp, err = SshExec(c.session, cmd)
	if err != nil {
		nflog.CdrwsLogger().ErrorNfLog("cdrws: Error executing command. %+v", err)
		if strings.Contains(err.Error(), "WaitForFunc failed") {
			c.status = Disconnected
		}
	} else {
		if err = xml.Unmarshal([]byte(resp), &reply); err != nil {
			nflog.CdrwsLogger().WriteNfLog(nflog.Error, "cdrws: fail to unmarshal reply")
		} else if isNlsDisconnected(reply) {
			err = errors.New("nls not connected")
			c.status = Disconnected
		}
	}
	respCh <- respChan{reply, err}
}
