func (a *tokenActor) syncToken2Sdrc(msgData *TokenNotifyMsg) {
	if msgData == nil {
		acslog.Error("msgData is nil.")
		return
	}
	if len(msgData.InstTokenMsg) == 0 {
		acslog.Error("instTokens is empty")
		return
	}
	for instId, tokenList := range msgData.InstTokenMsg {
		if tokenList == nil {
			acslog.Error("token list is nil, inst id[%d].", instId)
			continue
		}
		acslog.Info("sync token to sdrc! instId[%v] tokenListLen[%v]", instId, len(tokenList.Tokens))
		for tokenId, tokenType := range tokenList.Tokens {
			tokenInfo := TokenInfo{uint32(tokenId), uint8(tokenType)}
			a.SetTokenQueue(instId, cstype.UscDiscoveryService, tokenInfo)
		}
	}
}
