	if _, ok := dynamicTokenCached[appType]; !ok {
		dynamicTokenCached[appType] = &tokenInstData{make(map[uint32]uint64, 0)}
	}

	if _, ok := staticTokenCached[appType]; !ok {
		staticTokenCached[appType] = &tokenInstData{make(map[uint32]uint64, 0)}
	}
}
