	if tokenInstData, ok := staticTokenCached[appType]; ok {
		if staticCachedInstID, ok := tokenInstData.tokenInstMap[tokenInfo.TokenId]; ok {
			if staticCachedInstID == tokenInstId {
				acslog.Info("static token[%v] same InstID: [%v]", tokenInfo.TokenId, tokenInstId)
