		return
	}

	// 根据token类型设置token分组和存储在不同的MAP中
	var tokenGroup uint32
	switch tokenInfo.TokenType {
	case util.HttpStaticTokenType:
		tokenGroup = util.TokenGroupDefault
		staticTokenCached[appType].tokenInstMap[tokenInfo.TokenId] = tokenInstId
	case util.HttpDynamicTokenType:
		tokenGroup = util.TokenGroupHlbHash
		dynamicTokenCached[appType].tokenInstMap[tokenInfo.TokenId] = tokenInstId
	case util.DiscTokenType:
		tokenGroup = util.TokenGroupDisc
		staticTokenCached[appType].tokenInstMap[tokenInfo.TokenId] = tokenInstId
	default:
		tokenGroup = util.TokenGroupDefault
	}

	tokenDataInfo := TokenData{appType, tokenGroup, tokenInstId, tokenInfo.TokenId, SyncOp}
	if !a.isValidToken(tokenDataInfo) {
		acslog.Error("Invalid Token: [%v], return", tokenDataInfo)
		return
	}

	a.tokenEnqueue(tokenDataInfo)
}

