	const method = "getMsgFromEvent"
	if _, ok := e.GetMessage().(*transdsl.TimeoutEvent); ok { // 超时
		n.GetMetricReporter().NfDiscoveryTransTimeoutMetric()
		nfErr := nferr.New(gconst.AgfDo, "HandleEvent", "TimeoutEvent")
		nfErr = nfErr.WithErrCode(gconst.TimeOutWithIntermediateErr)
		n.GetPerfReporter().AddPerfByAGFReceiveTopoRspTimeout()
		n.GetErrStackLogger().PrintErrorStackWith(gconst.NfDiscRspTimeout,
			int32(topo.StatusCode_StatusGatewayTimeout), "transaction timeout")
		// 更改Topo的状态值为超时
		n.GetTopoContext().SetTopoStatus(gconst.TopoTimeOut)
		return nil, nfErr
	}

	dsToDoMsg, ok := e.GetMessage().(*dstodomsg.Ds2DoTopoDiscoveryResponses)
	// 收到错误的响应
	if !ok {
		n.GetLogger().Error("not expected Topo response message")
		nfErr := nferr.New(gconst.AgfDo, method, "not expected Topo response message")
		nfErr = nfErr.WithErrCode(gconst.AssertErr)
		n.GetTopoContext().SetTopoStatus(gconst.TopoOtherErr)
		return nil, nfErr
