	unavailableOcs := rsp.GetFilterPara().GetUnavailablePeer()
	if unavailableOcs == nil || len(unavailableOcs) == 0 {
		return false
	}

	filterOcs := n.GetFilterOcsManager().GetFilterOcsList()
	if filterOcs == nil || len(filterOcs) == 0 {
