	if d == nil || ctx == nil {
		return
	}
	switch msg := ctx.Message().(type) {
	case *actor.Started:
		d.started(ctx)
		cpu.Instance().RegSingleData(cpu.QueryOperator, d.SelfPID())
	default:
		d.msgProcAfterStarted(msg)
	}
}
func (d *QueryDomainSet) isNotReady() bool {
