func (d *QueryDomainSet) msgProcAfterStarted(msg interface{}) {
	if d.isNotReady() {
		logapi.Error("query %v ds is not ready", d.Self())
		return
	}
	switch msg := msg.(type) {
	case *cellmsg.MigrationNotify:
		d.onMigration(msg)
	case *sdrmsg.MsgStructV2:
		d.HandleSdrMessage(msg)
	case *actor.Restarting:
		d.restarting()
	case *actor.Stopping:
		d.stopping()
	case *actor.Stopped:
		d.stopped()
	case *actor.Terminated:
		d.terminated(msg)
	default:
		d.logReceivedUnexpectedMsg(msg)
	}
}
