func (d *overloadRsp) InitFcRspCfg(itf omcm.CfgDataItf) error {
	// 只要有一个ds更新全局变量中存储的MML数据即可
	if !atomic.CompareAndSwapUint32(&d.updateLock, 0, 1) {
		return nil
	}

	agfFcParas, err := omcmcfg.GetAGFFCPARA(itf)
	nflog.AgfLogger().WriteNfLog(nflog.Info, "Init flow ctrl, InitFcRspCfg GetAGFFCPARA, agfFcParas:"+
		" %+v, err: %+v", agfFcParas, err)
	if err != nil {
		atomic.CompareAndSwapUint32(&d.updateLock, 1, 0)
		return err
	}

	var ret error
	for _, fcPara := range agfFcParas {
		if err := d.setFcPara(fcPara); err != nil {
			ret = err
		}
	}

	if ret == nil {
		nflog.AgfLogger().WriteNfLog(nflog.Error, "Init AGFFCPARA success! ")
	}

	// 操作完后先休眠20ms再释放锁，避免其他ds做了同样的操作
	const sleepTime time.Duration = 20
	time.Sleep(sleepTime * time.Millisecond)
	atomic.CompareAndSwapUint32(&d.updateLock, 1, 0)
	return ret
}
