		metrics.Manager.DsMsg.TotalFcFlagNum.Reset()
		return false
	}

	overloadLevel := d.FcQueryOverload()
	algoStatus := d.flowctrCaseItf.FcAlgoStatus()
	d.WriteNfLog(nflog.Info, "flowCtrl, overloadLevel: %+v, algoStatus: {%+v}", overloadLevel, algoStatus)

	rspStatusCode := OverloadRspManager().obtainStatesCode(overloadLevel, algoStatus)

	rspResult := obtainRspResultByStatesCode(rspStatusCode)

	d.sendFlowCtrolRspMsg(&httpmsg.Message{Indicator: request.Indicator}, rspResult, request, rspStatusCode)

	d.WriteNfLog(nflog.Info, "Flow ctrl check, ctrled success")
	return true
}

