func (d *AgfDomainSet) localSessionOf(httpMsg *httpmsg.Message, httpMsgField *json.HttpMsgField) (*dbadpater.LocalChgSession, int64) {
	// 如果是Notify消息，不用查数据库
	if _, ok := httpMsg.Body.(*nchf.ChargingDataNotifyParameters); ok {
		localChgSession := &dbadpater.LocalChgSession{}
		return localChgSession, 0
	}

	_, ok := httpMsg.Body.(chgmsg.ChargingDataReqParameters)
	if !ok {
		return nil, 0
	}

	// http消息中请求字段为空，不是请求消息，返回
	if !httpMsgField.IsAllReqFieldValid() {
		return nil, 0
	}

	// 如果是update和release消息，则会话已经存在ddf，更新会话数据返回即可
	sessionKey := GetSessionKeyByChgReq(httpMsgField)

	// 如果软参值为0且是QBC场景，则使用ChargingDataRef作为key值
	if softpara.Ncg().DwValueOf(softpara.QbcIsUseChgDataRef) == softpara.QbcUseChgDataRef && d.IsQbcChgScene(httpMsgField.ReqField) {
		d.WriteNfLog(nflog.Info, "Dword22_BIt29 is 0 && isQbcChgScene, set ChargingDataRef as sessionKey")
		sessionKey = httpMsgField.ChargingDataRef
	}

	localChgSession, err := d.QueryLocalChgSession(sessionKey)
	if localChgSession == nil || err != nil {
		localChgSession = d.QueryLocalChgSessionByOldKeyAndDeleteDdf(sessionKey, httpMsgField)
	}

	// 若本地表为空则新生成一个返回去
	if localChgSession == nil {
		newLocalChgSession := dbadpater.GenerateLocalChgSessionByChargingDataRequest(sessionKey,
			httpMsgField.InvocationSequenceNumber, httpMsgField.InvocationTimeStamp)
		duration := LocalDurationOf(httpMsgField, newLocalChgSession)
		return newLocalChgSession, duration
	}

	duration := LocalDurationOf(httpMsgField, localChgSession)

	return localChgSession, duration
}
func (d *AgfDomainSet) AuditSessionHander(httpMsgField *json.HttpMsgField, msg *httpmsg.Message) {
	switch msg.Body.(type) {
	case *nchf.ChargingDataRefCreateParameters:
		// 不带Ref的请求消息在流程结束后处理
		d.IfAddtheAuditSessionPool(httpMsgField)
	case *nchf.ChargingDataUpdateParameters, *nchf.ChargingDataReleaseParameters:
		d.IfAddtheAuditSessionVolume(httpMsgField)
	default:
		// 如果是回放消息，则尝试清除审计消息表中对应的该审计消息
		if isFailureChgReq := chgmsg.IsFailureChgDataReq(msg); isFailureChgReq {
			metrics.Manager.Audit.FailureMsg.Inc()
			metrics.Manager.Audit.TotalFailureMsg.Inc()
			auditing.AuditInformation().ClearSession(httpMsgField.ChargingDataRef)
			return
		}
		return
	}
}
