func checkRcSendPlyFin(rcfItf rca.TraitRcf, tblType uint32) {
	acslog.Info("[rca] CheckRcSendPlyFin enter. tblType %v", tblType)
	rcCheckMapStateLock.Lock()
	defer rcCheckMapStateLock.Unlock()
	rcTaskMap := GetCheckTaskMap(tblType)
	if rcTaskMap == nil {
		return
	}
	for key := range rcTaskMap {
		if _, ok := rcTaskMap[key]; !ok {
			acslog.Error("[rca] CheckRcSendPlyFin rcTaskMap[key] is not exist. key:%v", key)
			break
		}
		// 异常场景保护，RCF异常中断核查事件，所有核查状态恢复初始化PolicyTaskInit，源端仍在进行策略下发
		if rcTaskMap[key].TaskStatus == PolicyTaskInit {
			acslog.Error("[rca] Policy task is init.")
			break
		}
		// 全量下发完成，对于状态非PolicyTaskChecking的核查策略，全部修改为Finish
		if rcTaskMap[key].TaskStatus != PolicyTaskChecking {
			rcTaskMap[key].TaskStatus = PolicyTaskFinish
			continue
		}
		// 此时策略全量下发完成或失败，需要给RCF回复对应核查策略的消息
		rcTaskMap[key].TaskStatus = PolicyTaskFinish
		if err := rcfItf.RcReportResult(rca.RcReportSendFin, rcTaskMap[key].RcEventObj); err != nil {
			acslog.Error("[rca] RcReportResult failed.")
