func (rcas RcaService) AsynPolicy(obj rca.RcObjectKeyItf, evtInfo rca.RcObjEvtInfoItf) rca.RcRetType {
	rcCheckMapStateLock.Lock()
	defer rcCheckMapStateLock.Unlock()

	tblType := obj.GetTblType()
	tblId := obj.GetTblId()
	// 如果是VPN类型直接返回成功
	if tblType == VpnRcResType {
		return rca.RcRetOk
	}
	// 根据资源类型获取不同的数据存储信息
	rcTaskMap := GetCheckTaskMap(tblType)
	if rcTaskMap == nil {
		acslog.Error("[rca] rcTaskMap is not exist. tblType:%v", tblType)
		return rca.RcRetErr
	}
	if _, ok := rcTaskMap[tblId]; !ok {
		acslog.Error("[rca] rcTaskMap[tblId] is not exist. tblId:%v", tblId)
		return rca.RcRetErr
	}
	// 存储核查信息
	rcTaskMap[tblId].RcEventObj.CsName = rcas.GetCsName()
	rcTaskMap[tblId].RcEventObj.CsType = rcas.GetCsType()
	rcTaskMap[tblId].RcEventObj.GroupId = rcas.GetGroupId()
	rcTaskMap[tblId].RcEventObj.Obj = obj
	rcTaskMap[tblId].RcEventObj.ObjContext = evtInfo.GetReportContext()

	// 此次核查事件时间戳（用来与上次核查事件时间戳比较）
	newRcEvtTimeStamp := evtInfo.GetReportContext().GetEvtChkTick()
	acslog.Info("cs[%v] tbl[%v %v] t[%v %v]", rcas.GetCsName(), tblType, tblId, rcEvtTimeStamp[tblType], newRcEvtTimeStamp)

	// 本次与之前时间戳不同，表示新的的事件，重新发起策略下发
	if rcEvtTimeStamp[tblType] != newRcEvtTimeStamp {
		// rcType策略初始化Init状态，导致全量下发策略，除本次核查为Checking状态，调整其余核查事件的状态为Associating
		rcTaskMap[tblId].TaskStatus = PolicyTaskChecking // 修改自己状态为PolicyTaskChecking
		rcEvtTimeStamp[tblType] = newRcEvtTimeStamp
		for key := range rcTaskMap {
			if key == tblId {
				continue
			}
			rcTaskMap[key].TaskStatus = PolicyTaskAssociating
		}
		// 根据资源类型发送策略重下通知
		sendPolicyByTblType(tblType)
		// 启动1分钟定时器，通知任务结束
		time.AfterFunc(1*time.Minute, func() {
			checkRcSendPlyFin(rcas.TraitRcf, tblType)
		})
		return rca.RcRetWait
	}

	// 保护机制1，Finish表示rctype策略为已经成功下发结束，并且时间戳rcEvtTimeStamp与此前已经下发时相同，不需要重复下发
	if rcTaskMap[tblId].TaskStatus == PolicyTaskFinish {
		acslog.Error("[rca] tbl type(%v) tbl Id(%v) has been finished.", tblType, tblId)
		return rca.RcRetOk
	}
	// PolicyTaskChecking表示RCF通知下发策略，但当前已下发，未下发完成，不需要重复下发；
	if rcTaskMap[tblId].TaskStatus == PolicyTaskAssociating {
		rcTaskMap[tblId].TaskStatus = PolicyTaskChecking
		acslog.Info("[rca] tbl type(%v) tbl Id(%v) is Checking.", tblType, tblId)
		return rca.RcRetWait
	}

	acslog.Error("[rca] Rcf policy check tbl type(%v) tbl Id(%v) is err.", tblType, tblId)
	return rca.RcRetErr
}

