func (o *ErrorProcessor) processUseOCSRspFOFH() (nchf32291.SessionFailover, nchf32291.FailureHandling) {
	// 首先从本地表会话中获取OCS响应中FO与FH，根据后续流程再更新ocsRspFO, ocsRspFH
	ocsRspFO, ocsRspFH := o.GetChgContext().Session().OcsRspFoFh()
	// 根据协议只有Create(对应201响应码)，Update(对应200响应码)中才会携带FO，FH字段，其他异常响应中不会携带
	if util.IsIorUSuccessRspCode(o.GetRecvRspHttpContext().RecvRspStatusCode()) {
		// 如果本会话还未获取过OCS响应中FO与FH，则解析OCS响应，并设置已获取标志位
		if o.GetChgContext().Session().OcsRspFoFhValueReadStatusFlag() == 0 {
			ocsRspFoFhInfo := o.getOcsRspFOFH()
			ocsRspFO = ocsRspFoFhInfo.OcsRspFo
			ocsRspFH = ocsRspFoFhInfo.OcsRspFh
			o.GetChgContext().Session().SetOcsRspFoFhValueReadStatusFlag()
			o.GetChgContext().Session().SetOcsRspFoFh(ocsRspFO, ocsRspFH)
			o.GetLogger().Info("ocsRspFo(%d),ocsRspFh(%d), FO:NOT_SUPPORTED(1)/SUPPORTED(2),FH:T(1)/C(2)/R&T(3)",
				ocsRspFO, ocsRspFH)
		}
		// 正常响应按照透传正常处理并返回
		return o.getFailStrategyByCode(o.GetRecvRspHttpContext().RecvRspStatusCode())
	}

	// 400,403,404协议要求透传，但是不携带FO，FH字段，直接按照透传处理
	if util.IsPassThroughCode(o.GetRecvRspHttpContext().RecvRspStatusCode()) {
		return o.getFailStrategyByCode(o.GetRecvRspHttpContext().RecvRspStatusCode())
	}

	// 其他错误码先获取配置信息，如果本地表会话中有OCS响应中的FO、FH就更新，否者继续使用配置中FO、FH
	fo, fh := o.getFailStrategyByCode(o.GetRecvRspHttpContext().RecvRspStatusCode())
	// 如果错误码配置了ALWAYSCONTINUE
	if fh != util.FailureHandlingALWAYSCONTINUE {
		if ocsRspFO != nchf32291.SessionFailoverINVALID {
			fo = ocsRspFO
		}
		if ocsRspFH != nchf32291.FailureHandlingINVALID {
			fh = ocsRspFH
		}
	}

	return fo, fh

}
func (o *ErrorProcessor) modOCSRspFOFH() {
	// 根据协议只有Create(对应201响应码)，Update(对应200响应码)中才会携带FO，FH字段，其他响应中不会携带
	if !util.IsIorUSuccessRspCode(o.GetRecvRspHttpContext().RecvRspStatusCode()) {
		return
	}
	// 如果会话之前消息已经确定不需要修改，则直接返回
	if o.GetChgContext().Session().OcsRspFoFhValueModStatusFlag() != 0 {
		return
	}

	// 会话第一次成功OCS响应需要解析以获得FO，FH
	// 由于同一会话每条OCS响应中FH，FO位置不一定相同，所以若发现OCS响应需要修改每条消息都需要解析，直到OCS响应正常
	ocsRspFoFhInfo := o.getOcsRspFOFH()

	// 如果会话已经度过OCS响应情况，不用重新设置
	if o.GetChgContext().Session().OcsRspFoFhValueReadStatusFlag() == 0 {
		o.GetChgContext().Session().SetOcsRspFoFhValueReadStatusFlag()
		o.GetChgContext().Session().SetOcsRspFoFh(ocsRspFoFhInfo.OcsRspFo, ocsRspFoFhInfo.OcsRspFh)
	}

	createOrUpdateRsp, ok := o.GetRecvRspHttpContext().RecvRspHttpMsg().GetBody().(chgmsg.ChargingDataCreateOrUpdateRsp)
	if !ok {
		return
	}

	tmpRsp := createOrUpdateRsp.GetChargingDataResponse()

	switch getModOCSRspFOFHStatus(ocsRspFoFhInfo.OcsRspFo, ocsRspFoFhInfo.OcsRspFh) {
	case gconst.ModFoStatus:
		// 修改FO
		rsp := json.ModStringField(&tmpRsp, "FAILOVER_SUPPORTED", ocsRspFoFhInfo.FoValueBeginIndex, ocsRspFoFhInfo.FoValueEndIndex)
		chgmsg.SetChgDataRspOfRsp(createOrUpdateRsp, rsp)
	case gconst.ModFHStatus:
		// 修改FH
		rsp := json.ModStringField(&tmpRsp, "CONTINUE", ocsRspFoFhInfo.FhValueBeginIndex, ocsRspFoFhInfo.FhValueEndIndex)
		chgmsg.SetChgDataRspOfRsp(createOrUpdateRsp, rsp)
	case gconst.ModFoFHStatus:
