func checkStatusAndEventType(status nnrf29510.NFStatus, record *ddftbl.CachedPnfProfile) bool {
	if status == nnrf29510.NFStatusAll {
		return true
	}
	// 双活异常场景下暂停状态的NF仍保持可用
	return (record.NfStatus == status && record.NotifyEventType != nnrf29510.NotificationEventTypeNfDeregistered) ||
		(record.DoubleChainStatus == common.DoubleChainBroken && record.NfStatus == nnrf29510.NFStatusSUSPENDED)
}

func (qu *QueryUtil) queryNfProfileByIdAndStatus(instanceIds map[uint32]string,
	status nnrf29510.NFStatus) ([]*ddftbl.CachedPnfProfile, QueryRet, []uint32) {

	profileTbls, agingList, allowedGroupId := make([]*ddftbl.CachedPnfProfile, 0, 0), make([]uint32, 0), make(map[string]uint8, 0)
	foundProfile := false
	for instanceId, groupId := range instanceIds {
		record := qu.getCachedPnfProfile(instanceId)
		if record == nil {
			continue
		}
		// 如果此groupid之前没有检测过，则需要使用IsTargetProfile校验
		if _, ok := allowedGroupId[groupId]; !ok && !qu.IsTargetProfile(record) {
			continue
		}
		allowedGroupId[groupId] = 0
		if len(qu.Param.TargetNfType) == 0 {
			// routingbinding查询缓存可以不带nf类型，因此需要填充下，否则会导致删除老化记录失败（查询结果只会是同个nf类型）
			qu.Param.TargetNfType = nnrf29510.NFTypeName[int32(record.NfType)]
		}

		if qu.isRecordNeedAging(record, &agingList) {
			continue
		}

		foundProfile = true
		if checkStatusAndEventType(status, record) {
			profileTbls = append(profileTbls, record)
		}

	}

	if !foundProfile {
		return profileTbls, QueryNotFound, agingList
	}

	if len(profileTbls) == 0 {
		return profileTbls, QueryStatusUnavailable, agingList
	}

	return profileTbls, QueryFoundSucc, agingList
}

func (qu *QueryUtil) getCachedPnfProfile(instanceId uint32) *ddftbl.CachedPnfProfile {
	filter := qu.GetQueryFilter().GetFilter(profilePrimaryFilter)
	instIdCondIndex := 0
	SetFilter(filter, instIdCondIndex, instanceId)
	recordItf, err := qu.Data.Query(ddftbl.TableNameCachedPnfProfile, filter)
	if recordItf == nil || err != nil {
		logapi.Error("getCachedPnfProfile fail! nfId[%v]err [%v]",
			nfidmapmgmt.GetInstanceIdByValue(instanceId), err)
		return nil
	}
	record, ok := recordItf.(*ddftbl.CachedPnfProfile)
	if !ok {
		logapi.Error("getCachedPnfProfile profile fail!")
		return nil
	}
	return record
}

func checkNfStatus(nfStatus nnrf29510.NFStatus, isDoubleBrokenChain uint32) bool {
	return nfStatus == nnrf29510.NFStatusREGISTERED ||
		(nfStatus == nnrf29510.NFStatusSUSPENDED && isDoubleBrokenChain == common.DoubleChainBroken)
}

// queryNfProfileByNftype 根据nftype查询profile
func (qu *QueryUtil) queryNfProfileByNftype() ([]*ddftbl.CachedPnfProfile, QueryRet, []uint32) {
	logapi.Info("queryNfProfileByNftype start! TargetNfType[%v]", qu.Param.TargetNfType)
	profileTbls, agingList := make([]*ddftbl.CachedPnfProfile, 0, 0), make([]uint32, 0)
	foundProfile := false
	nftype, ok := nnrf29510.NFTypeValue[qu.Param.TargetNfType]
	if !ok {
		return profileTbls, QueryNotFound, agingList
	}

	records := qu.getRecordsWithNfType(nftype)
	if records == nil {
		return profileTbls, QueryNotFound, agingList
	}

	for _, record := range records {
		if !qu.IsTargetProfile(record) {
			continue
		}
		if qu.isRecordNeedAging(record, &agingList) {
			continue
		}
		foundProfile = true
		// 双活故障场景下暂停状态的NF仍保持可用
		if checkNfStatus(record.NfStatus, record.DoubleChainStatus) {
			profileTbls = append(profileTbls, record)
		}
	}

	if !foundProfile {
		logapi.Error("queryNfProfileByNftype fail! reason QueryNotFound")
		return profileTbls, QueryNotFound, agingList
	}

	if len(profileTbls) == 0 {
		logapi.Error("queryNfProfileByNftype fail! reason QueryStatusUnavailable")
		return profileTbls, QueryStatusUnavailable, agingList
	}
	logapi.Info("queryNfProfileByNftype succeed! length[%v]", len(profileTbls))
	return profileTbls, QueryFoundSucc, agingList
}

