func (qu *QueryUtil) checkNotifyTypeParam(profileTbl *ddftbl.CachedPnfProfile, serviceTbl *ddftbl.CachedPnfService) bool {
	// 如果不指定notificationType查询，无需填充callbackUri，也无需根据该条件过滤。
	if len(qu.getQueryDefaultNotificationType()) == 0 {
		return true
	}
	if qu.matchDefaultNotification(profileTbl.DefaultNotificationSubscriptions) {
		return true
	}
	return qu.matchDefaultNotification(serviceTbl.DefaultNotificationSubscriptions)
}

func (qu *QueryUtil) matchDefaultNotification(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription) bool {
	if len(qu.getQueryDefaultNotificationType()) == 0 {
		return true
	}
	// 如果cache中的没有defaultNotificationSubs，则认为该profile/service是不匹配的
	if len(defaultNotificationSubs) == 0 {
		return false
	}
	switch qu.getQueryDefaultNotificationType() {
	case nnrf29510.N1Messages:
		return checkN1Class(defaultNotificationSubs, qu.getCacheQueryMsg())
	case nnrf29510.N2Information:
		return checkN2Class(defaultNotificationSubs, qu.getCacheQueryMsg())
	default:
		return checkOtherType(defaultNotificationSubs, qu.getCacheQueryMsg())
	}
}

func checkN2Class(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
			continue
		}
		if queryMsg.N2InfoClass == defaultNotificationSubs[idx].N2InformationClass {
			return true
		}
	}
	return false
}

func checkN1Class(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
			continue
		}
		if queryMsg.N1MsgClass == defaultNotificationSubs[idx].N1MessageClass {
			return true
		}
	}
	return false
}

func checkOtherType(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
