// queryNfService 查询service
func (qu *QueryUtil) queryNfService(profileTbls []*ddftbl.CachedPnfProfile, instIdMap map[uint32]string) ([]*cachemsg.NrfService, map[uint32]uint32, QueryRet) {
	serviceList := make([]*cachemsg.NrfService, 0, 0)
	invalidProfileInstanceIds := make(map[uint32]uint32, 0)

	foundService := false
	amfTimeout := false
	for _, profileTbl := range profileTbls {
		serviceTbls := qu.queryNfServiceWithProfileTbl(profileTbl)
		insId := nfidmapmgmt.GetInstanceIdByValue(profileTbl.NfInstanceId)
		instIdMap[profileTbl.NfInstanceId] = insId

		isProfileValid := false
		for _, serviceTbl := range serviceTbls {
			if !qu.IsTargetService(serviceTbl) {
				logapi.Info("queryNfService service invalid SrvInstanceId[%v]!", serviceTbl.SrvInstanceId)
				continue
			}
			if !qu.checkNotifyTypeParam(profileTbl, serviceTbl) {
				logapi.Info("queryNfService service default notification class not match. [instance id:%s]!", serviceTbl.SrvInstanceId)
				continue
			}
			isProfileValid = true
			foundService = true
			serviceList = append(serviceList, qu.getRegService(insId, profileTbl, serviceTbl)...)
		}

		amfTimeout = qu.checkAmfHotSpare(profileTbl.RecordTime)

		// 默认通知消息路由查询时如果profile的信息不匹配，并且该profile下的所有service的信息也不匹配，需要将该profile从结果剔除
		if !isProfileValid && !qu.matchDefaultNotification(profileTbl.DefaultNotificationSubscriptions) {
			invalidProfileInstanceIds[profileTbl.NfInstanceId] = 1
		}
	}

	if !foundService {
		logapi.Info("find nf service fail! QueryNotFound")
		return serviceList, invalidProfileInstanceIds, QueryNotFound
	}

	if len(serviceList) == 0 {
		logapi.Info("find nf service fail! QueryStatusUnavailable")
		return serviceList, invalidProfileInstanceIds, QueryStatusUnavailable
	}

	logapi.Info("find nf service success!")
	if qu.checkMainAmfInfo(amfTimeout) {
		return serviceList, invalidProfileInstanceIds, QueryResultCanBeUse
	}
	return serviceList, invalidProfileInstanceIds, QueryFoundSucc
}

