func (o *obj) DecompressContent(content []byte) ([]byte, error) {
	emptyRes := make([]byte, 0, 0)
	if len(content) < CompressDataLenOffset {
		logapi.Error("content[%v] len[%v] is invalid!", content, len(content))
		return emptyRes, discerrors.NewErr("content len is invalid")
	}

	srcDataLen, err := common.BytesToInt(content[:SrcDataLenOffset])
	if err != nil {
		logapi.Error("get src data len fail!")
		return emptyRes, err
	}

	compressDataLen, err := common.BytesToInt(content[SrcDataLenOffset:CompressDataLenOffset])
	if err != nil {
		logapi.Error("get compress data len fail!")
		return emptyRes, err
	}
	logapi.Info("srcDataLen[%v] compressDataLen[%v]", srcDataLen, compressDataLen)

	data := content[CompressDataLenOffset:]
	if len(data) != int(compressDataLen) {
		logapi.Error("data len[%v][%v] is invalid!", len(data), compressDataLen)
		return emptyRes, discerrors.NewErr("data len is invalid")
	}

	decompressData := make([]byte, srcDataLen, srcDataLen)
	decompressDataLen, err := lz4.UncompressBlock(data, decompressData)
	if err != nil {
		logapi.Error("decompress fail[%v]!", err)
		return emptyRes, err
	}

	if int(srcDataLen) != decompressDataLen {
		logapi.Error("decompress data len[%v][%v] is invalid!", srcDataLen, decompressDataLen)
		return emptyRes, discerrors.NewErr("decompress data len is invalid!")
	}

	return decompressData, nil
}
