func (s *sdrBaseActor) cmfMicroServiceNotifyProc(notify cmf.CsDetailNotifyItf) {
	acslog.Error("csr notify[%v]", notify)
	microNotifyMutex.Lock()
	defer microNotifyMutex.Unlock()
	action := notify.GetNotifyAction()
	status := notify.GetCsStatus().Status.SStatus
	serviceName := notify.GetSrvName()
	appType := uint32(cstype.SrvNameAppTypeTable[serviceName])
	instID := notify.GetInstanceID()
	podId := notify.GetPodID()
	serviceVersion := notify.GetVersion()
	if serviceVersion != api.DefaultVersion {
		acslog.Error("version does not match, serviceName: [%v], version: [%v]", serviceName, serviceVersion)
		return
	}
	if instID == 0 {
		acslog.Error("invalid instID")
		return
	}
	acslog.Error("action:%v, status:%v, serviceType:[%v]", action, status, appType)
	if action == csr.CsrActionCreate || action == csr.CsrActionUpdate {
		dealWithActionCreateOrUpdate(serviceName, instID)
	} else {
		// DELETE
		dealWithActionDelete(serviceName, instID)
	}
	// 当Service Status 为 NotReady 时，定为Delete 事件，FE侧不处理dbbroker的not ready信息
	if appType != cstype.UscDbBrokerService {
		if status != haf.SvcStatusReady {
			acslog.Error("set delete at [%v] notready", appType)
			action = csr.CsrActionDelete
		}
	}

	updateDiscInstInfo(notify, appType, status, instID)

	if api.ServiceNotifyProcCallBack != nil {
		api.ServiceNotifyProcCallBack(podId, appType, instID, getActionFlag(action))
	}
}
func updateDiscInstInfo(notify cmf.CsDetailNotifyItf, appType uint32, status haf.SvcStatus, instID uint64) {
	if appType == cstype.UscDiscoveryService {
		if status == haf.SvcStatusReady {
			api.ServiceReadyInstInfo.Add(appType, instID)
		} else {
			api.ServiceReadyInstInfo.Del(appType, instID)
		}
		acslog.Error("ready instance info[%v]", api.ServiceReadyInstInfo.Info)
		workStatus := notify.GetLabel("WorkStatus")
		acslog.Error("disc work status[%v]", workStatus)
		if workStatus == "Ready" {
			api.DiscStartWorkingInstInfo.Add(appType, instID)
		} else {
			api.DiscStartWorkingInstInfo.Del(appType, instID)
		}
	}
}
func dealWithActionCreateOrUpdate(srvName string, iid uint64) {
	exist := false
	for _, v := range api.ServiceInstListMap[srvName] {
		if v == iid {
			acslog.Error("service instance %v already exist", iid)
			exist = true
			break
		}
	}
	if !exist {
		acslog.Error("add service instance %v/%v", srvName, iid)
		api.ServiceInstListMap[srvName] = append(api.ServiceInstListMap[srvName], iid)
	}
}
func dealWithActionDelete(srvName string, iid uint64) {
	for i, v := range api.ServiceInstListMap[srvName] {
		if v == iid {
			acslog.Error("delete service instance %v/%v", srvName, iid)
			// 最后一个元素
			if (i + 1) == len(api.ServiceInstListMap[srvName]) {
				api.ServiceInstListMap[srvName] = api.ServiceInstListMap[srvName][:i]
			} else {
				api.ServiceInstListMap[srvName] = append(api.ServiceInstListMap[srvName][:i], api.ServiceInstListMap[srvName][i+1:]...)
			}
			break
		}
	}
}
func getActionFlag(action csr.Action) uint32 {
	switch action {
	case csr.CsrActionCreate:
		return api.ActionCreate
	case csr.CsrActionDelete:
		return api.ActionDelete
	case csr.CsrActionUpdate:
		return api.ActionUpdate
	default:
		return api.ActionDefault
	}
}

