func replacePort(url string) string {
	index := findLastAddressSeparatorIndex(url)
	if index < 0 || index >= len(url) {
		return constEmptyStr
	}
	return url[0:index+1] + constOmgServerPort
}
func findLastAddressSeparatorIndex(url string) int {
	for i := len(url) - 1; i >= 0; i-- {
		if url[i] == constAddressSeparatorChar {
			return i
		}
		// ipv6地址不带端口
		if url[i] == constRightMiddleBracketChar {
			return -1
		}
		// ipv4地址不带端口
		if url[i] == constBackslashChar {
			return -1
		}
	}
	// 地址不带端口并且不带https://前缀
	return -1
}
