			err := fmt.Errorf("panic: %v", panicErr)
			log.Logger().WriteLog(log.Error, "fail to send request: %v", err)
		}
	}()

	header := make(map[string][]string, 2)
	if method == http.MethodPut || method == http.MethodPost {
