	}

	resp, err := api.NewCspRestInvoker().Invoke(method, reqURL, header, body)
	if resp == nil {
		log.Logger().WriteLog(log.Error, "Cse RestInvoker failed, *rest.Response is nil, error: %v", err)
		return http.StatusInternalServerError, "", err
	}
	defer resp.Close()

	if err != nil {
		log.Logger().WriteLog(log.Error, "do request failed, error: %v", err)
		return resp.GetStatusCode(), "", err
	}

