func (n *NfDiscReqBuilder) buildSearchParaByAGFFuncPara(searchPara *topo.SearchPara) *topo.SearchPara {
	// 从mml（AGF功能参数信息AGFFUNCPARA）中获取OCS的选择策略
	agfFuncPara, err := omcmcfg.MmlCfgCache().Query(n.GetOmcmCfger(), omcmcfg.NameAgfFuncPara, nil)
	if err != nil {
		// 默认同时采用supi和gpsi去发现ocs
		n.GetLogger().Warning("GetAGFFUNCPARA failed {%+v}, use both supi and gpsi to discovery ocs.", err)
		searchPara.Supi = n.GetChgContext().Session().Supi()
		searchPara.Gpsi = n.GetChgContext().Session().Gpsi()
		searchPara.Dnn = n.GetTopoContext().Dnn()
		return searchPara
	}

	isValidOcsDiscoveryPolicy := false
	ocsDiscPlcy := agfFuncPara.(*cm_go.AGFFUNCPARA).OCSDISCPLCY
	if (ocsDiscPlcy & 1) == 1 {
		searchPara.Supi = n.GetChgContext().Session().Supi()
		isValidOcsDiscoveryPolicy = true
	}
	if ((ocsDiscPlcy >> 1) & 1) == 1 {
		searchPara.Gpsi = n.GetChgContext().Session().Gpsi()
		isValidOcsDiscoveryPolicy = true
	}

	const lenOfDnnOffset uint32 = 2
	if ((ocsDiscPlcy >> lenOfDnnOffset) & 1) == 1 {
		searchPara.Dnn = n.GetTopoContext().Dnn()
		isValidOcsDiscoveryPolicy = true
	}

	if !isValidOcsDiscoveryPolicy {
		n.GetLogger().Warning("agfFuncPara.OCSDISCPLCY is invalid: %v, use both supi and gpsi to discovery ocs.", ocsDiscPlcy)
		searchPara.Supi = n.GetChgContext().Session().Supi()
		searchPara.Gpsi = n.GetChgContext().Session().Gpsi()
		searchPara.Dnn = n.GetTopoContext().Dnn()
	}

