	}

	// 构造服务发现请求的时候根据该标志决定TOPO发现时是否关心OCS状态
	n.GetTopoContext().SetIsDiscOcsIgnoreOcsLink(isDiscOcsIgnoreOcsLink)
	msg, err := n.constructNfDiscoveryReq()
	if err != nil || msg == nil {
		if !n.isErrOcsFiltered(err) {
