	plmnid := ngHplmn.Mcc + "|" + ngHplmn.Mnc
	nflog.AgfLogger().ErrorNfLog("Add NgHplmn: %+v", ngHplmn)
	m.plmnidMap.Store(plmnid, ngHplmn.Noid)

