func calcIdxNum(maxVal uint64, step uint32) uint32 {
	/*
		举例，end-start+1是以下几种典型值，对应的idx：
			76, 100
			100, 1000
		所以，下面log函数计算后，需要加1。log1000是3，idx最大值需要是10000
	*/
	if step == Decimal {
		return uint32(math.Log10(float64(maxVal))) + RoundUpNum
	} else if step == Hexadecimal {
		return uint32(math.Log2(float64(maxVal)))/uint32(math.Log2(float64(Hexadecimal))) + RoundUpNum
	}
	return 0
}
