	} else if event == http.StateHijacked || event == http.StateClosed {
		log.Logger().WriteLog(log.Info, "tcp conn closed,remoteAddr:%s,localAddr:%s", conn.RemoteAddr().String(), conn.LocalAddr().String())
		connsLock.Lock()
