func (client *HttpClient) StartServer() {
	ch := make(chan bool, 1)
	client.cmServerStatus = UnStart
	for UnStart == client.cmServerStatus {
		client.cmServerStatus = Starting
		for {
			if !client.IsInvalidLocalPort() {
				break
			}
			if err := client.Init(); err != nil {
				log.Logger().WriteLog(log.Error, "cdrws: client Init failed(%s), retry in 500ms later", err.Error())
				time.Sleep(constSleepTime * time.Millisecond)
				continue
			}
			log.Logger().WriteLog(log.Info, "cdrws: client Init success")
			break
		}

		var localURL string
		go func() {
			i := 0
			for {
				if !client.IsInvalidLocalPort() {
					log.Logger().WriteLog(log.Info, "cdrws: local port is valid(%d)",
						client.GetLocalPort())
					break
				}
				time.Sleep(1 * time.Second)
				i++
				log.Logger().WriteLog(log.Error, "cdrws: local port is invalid,"+
					" sleep 1 second. wait for %d time", i)
				// 等待3秒还未获取到本地端口，重新生成端口
				if i >= constPortWaitTime {
					ch <- false
					return
				}
			}

			localURL = client.GetLocalHTTPAddr()
			log.Logger().WriteLog(log.Info, "cdrws: get local addr:%s.", localURL)
			Conns = make(map[string]net.Conn)
			client.serverObj = &http.Server{Addr: localURL, ConnState: ConnStateEvent, TLSConfig: client.tlsConfigServer}
			err := client.serverObj.ListenAndServeTLS("", "")
			if err != nil {
				log.Logger().WriteLog(log.Warning, "cdrws: call httpagent.ListenAndServe"+
					" failed(%s), Reregistration", err.Error())
				// 如果失败，就需要重新获取端口，可能是端口被占用了
				ch <- false
			}

		}()

		select {
		case _, ok := <-ch:
			if !ok {
				log.Logger().WriteLog(log.Error, "cdrws: listen channel has closed.")
				return
			}
			client.cmServerStatus = UnStart
			client.SetLocalPortInvalid()
			log.Logger().WriteLog(log.Error, "cdrws: listen httpclient addr failed, retry.")
			continue
		case <-time.After(constWaitTime * time.Second):
			log.Logger().WriteLog(log.Critical, "cdrws: Success to listen on: %s", localURL)
			client.cmServerStatus = Started
		}
	}
	close(ch)
}
