}
func SendPostDynSubscibe(url string, body io.Reader, head map[string]string, timeOut time.Duration, tlsCfg *tls.Config) (rsp *http.Response, err error) {
	client := http.Client{
		Timeout:   timeOut,
		Transport: &http.Transport{TLSClientConfig: tlsCfg, DisableKeepAlives: true},
	}
	req, err := http.NewRequest("POST", url, body)
	if err != nil {
		return nil, err
	}
	if len(head) > 0 {
		for k, v := range head {
			req.Header.Set(k, v)
		}
	}
	rsp, err = client.Do(req)
	if err != nil {
		log.Logger().WriteLog(log.Error, "failed to send request,%v", err)
	}
	return
}

