				e.onTimeOutMsg(msg)
			case *interval:
				e.onIntervalMsg(msg)
			case *sdrply.CheckTokenPly:
				e.onCheckTokenPly(msg)
			default:
				// 处理启动后的消息
				e.msgProcAfterStarted(next, rc, envelope)
			}
		}
		return fn
	}
	return middleware
}
