func GetFoAndFhFromCcpFot(ccpFot *cmgoagf.CCPFOT) (nchf32291.SessionFailover, nchf32291.FailureHandling) {
	fo := nchf32291.SessionFailoverFAILOVER_SUPPORTED
	fh := nchf32291.FailureHandlingCONTINUE

	if ccpFot == nil {
		return fo, fh
	}

	if ccpFot.FOENABLE == cmgoagf.AGFFOENABLE_TYPEFALSE {
		fo = nchf32291.SessionFailoverFAILOVER_NOT_SUPPORTED
	}

	if ccpFot.FH == cmgoagf.AGFFH_TYPETERMINATE {
