func (serviceDo *object) addNfListToUpdateQueue(nfType int32, itemLinks []*sbi29571.Link) {
	oldRecords := serviceDo.QueryNFWithNFType(nnrf29510.NFType(nfType))
	oldRecordIds := make(map[uint32]uint32, len(oldRecords))
	for _, v := range oldRecords {
		oldRecordIds[v.NfInstanceId] = 0
	}
	instIdList := make([]string, len(itemLinks))
	currentTime := time.Now().Unix()
	for i, link := range itemLinks {
		split := strings.Split(link.Href, "/")
		if len(split) == 0 {
			logapi.Error("link[%v] invalid!", link.Href)
			continue
		}
		splitInstId := strings.Split(split[len(split)-1], "&")
		instId := splitInstId[0]
		updateTime := serviceDo.getUpdateTime(splitInstId, link)
		instIdList[i] = instId
		instanceID := nfidmapmgmt.AssignValueForNfInstanceIdMap(instId, nfidmapmgmt.ExistCache)
		record := serviceDo.QueryNFWithNFId(instanceID)
		delete(oldRecordIds, instanceID)
		if record == nil || record.ExpiredAt <= currentTime || record.RecordTime < updateTime {
			logapi.Info("insert inst[%v][%v] to query queue!", nfType, instId)
			innerupdate.UpdateQueueInst().Add(httpnnrf29510.NFType(nfType), instId)
		}
	}
	for instanceID := range oldRecordIds {
		// 将nfList查询结果中没有，但是本地有缓存的NF加到更新队列中，更新队列根据instanceid查nrf，查询结果为空时删除对应的缓存
		instId := nfidmapmgmt.GetInstanceIdByValue(instanceID)
		logapi.Info("insert invalid inst[%v][%v] to query queue!", nfType, instId)
		innerupdate.UpdateQueueInst().Add(httpnnrf29510.NFType(nfType), instId)
	}
	nrfnfquery.StartWorkMgrInst().UpdateNfList(httpnnrf29510.NFType(nfType), instIdList)
}
