	if len(selfLink) == 0 {
		logapi.Warning("[Inner Interface Message Trace] self link is invalid! nfType[%v]", qryNfType)
		nrfnfquery.StartWorkMgrInst().UpdateNfList(httpnnrf29510.NFType(qryNfType), []string{})
		// nflist查询结果为空时删除对应nf类型的nf
		serviceDo.sendNFListRetrievalDeleteData(0, qryNfType, true)
