func (serviceDo *object) handleNrfDoubleChainStatus(qryNfType nnrf29510.NFType, isDoubleBrokenChain uint32) {
	currentTime := time.Now().Unix()
	// 双活故障，记录故障时间，刷新双活状态
	if isDoubleBrokenChain == common.DoubleChainBroken {
		common.NrfDoubleChain.OldStatus = isDoubleBrokenChain
		common.NrfDoubleChain.FaultTime = currentTime
		serviceDo.handleInnerUpdateDoubleChainStatusMsg(qryNfType, isDoubleBrokenChain)
		return
	}

	// 双活故障到恢复时,11分钟 + 检索周期后刷新NF数据
	if common.NrfDoubleChain.OldStatus == common.DoubleChainBroken &&
		(currentTime-common.NrfDoubleChain.FaultTime) > (common.NrfDbCheckPeriod+int64(nrfnfseg.GetNfListQueryPeriod())) {
		serviceDo.handleInnerUpdateNf()
		// 只触发一次
		common.NrfDoubleChain.OldStatus = isDoubleBrokenChain
	}
}
func (serviceDo *object) isAllowUpdateDoubleChainStatus(isDoubleBrokenChain uint32) bool {
	currentTime := time.Now().Unix()
	// 双活故障到恢复之后，11分钟内不允许修改双活状态
	if isDoubleBrokenChain == common.DoubleChainNormal && currentTime-common.NrfDoubleChain.FaultTime < common.NrfDbCheckPeriod {
		return false
	}
	return true
}

