func (d *QueryDomainSet) Receive(ctx actor.Context) {
	if d == nil || ctx == nil {
		return
	}
	switch msg := ctx.Message().(type) {
	case *actor.Started:
		d.started(ctx)
		cpu.Instance().RegSingleData(cpu.QueryOperator, d.SelfPID())
	default:
		d.msgProcAfterStarted(msg)
	}
}
func (d *QueryDomainSet) isNotReady() bool {
	return d.Context == nil || d.DoActorManager == nil
}
func (d *QueryDomainSet) msgProcAfterStarted(msg interface{}) {
	if d.isNotReady() {
		logapi.Error("query %v ds is not ready", d.Self())
		return
	}
	switch msg := msg.(type) {
	case *cellmsg.MigrationNotify:
		d.onMigration(msg)
	case *sdrmsg.MsgStructV2:
		d.HandleSdrMessage(msg)
	case *actor.Restarting:
		d.restarting()
	case *actor.Stopping:
		d.stopping()
	case *actor.Stopped:
		d.stopped()
	case *actor.Terminated:
		d.terminated(msg)
	default:
		d.logReceivedUnexpectedMsg(msg)
	}
}
func (d *QueryDomainSet) HandleSdrMessage(msg *sdrmsg.MsgStructV2) {
	switch req := msg.PayLoad.(type) {
	case *cachemsg.CacheQueryReq:
		d.handleQueryMessage(req)
	case *cachemsg.CacheQueryNfReq:
		d.handleQueryNfMessage(req)
	default:
		d.logReceivedUnexpectedMsg(msg)
	}
}
func (d *QueryDomainSet) handleQueryMessage(msg *cachemsg.CacheQueryReq) {
	instId := (uint64(msg.Header.ServiceId) << headerOffset) + uint64(msg.Header.SrcMid)

	for _, message := range msg.MsgList {
		d.handleQueryMsg(message, instId, msg.AgingFlag)
	}
}

