func (d *QueryDomainSet) getQueryRsp(message *cachemsg.CacheQueryMsg, agingFlag bool) *cachemsg.CacheResponse {
	if cpu.Instance().IsMsgNeedControl(cpu.QueryOperator, d.SelfPID()) {
		return common.GetEmptyCacheResponse(message.SenderId, uint32(nfquery.QueryFlowControlled))
	}

	deleteDataList, queryRsp := nfquery.QueryMgrInst().HandleQueryMsg(d, message, d.filter, agingFlag)
	d.handleDeleteDataList(deleteDataList)
	d.handleEarlyReq(queryRsp)
	if queryRsp == nil {
		queryRsp = common.GetEmptyCacheResponse(message.SenderId, uint32(nfquery.QueryInternalErr))
	}
	return queryRsp
}
func (d *QueryDomainSet) handleDeleteDataList(deleteDataList *datatrace.DeleteDataList) {
	if deleteDataList == nil {
		return
	}
	logapi.Info("send AgingList size %v", len(deleteDataList.AgingList))
	if !nrfnfseg.GetColocateSwt() {
		d.Send(insertds.InsertDomainSetPid, deleteDataList)
		return
	}
	// 融合部署时，不进行老化，去进行更新
	for _, v := range deleteDataList.AgingList {
		innerupdate.UpdateQueueInst().Add(httpnnrf29510.NFType(deleteDataList.NfType), nfidmapmgmt.GetInstanceIdByValue(v))
	}
}
func (d *QueryDomainSet) handleQueryMsg(message *cachemsg.CacheQueryMsg, instId uint64, agingFlag bool) {
	if message == nil {
		return
	}
	d.delayMetric.RecvNfDiscReq()
	metric.Discovery().NfDisc.TotalNfDiscReq.Inc()
	metric.Discovery().NfDisc.NfDiscReq.Inc()
	queryRsp := d.getQueryRsp(message, agingFlag)
	sdrapi.SendSdrMsgByInstance(queryRsp, instId, topic.TopicDdfCacheQueryResponse)
	for _, instance := range queryRsp.Instances {
		common.PutNrfInstanceObj(instance)
	}
	if queryRsp.RetCode <= uint32(nfquery.QueryInternalErr) {
		metric.Discovery().NfDisc.TotalNfDiscRsp[queryRsp.RetCode].Inc()
		metric.Discovery().NfDisc.NfDiscRsp[queryRsp.RetCode].Inc()
	}
	d.delayMetric.SendNfDiscRsp()
}
func (d *QueryDomainSet) handleQueryNfMessage(req *cachemsg.CacheQueryNfReq) {
	queryRsp := &cachemsg.CacheQueryNfResponse{
		Header:    common.GetMsgHeader(sdrapi.PidScph, common.HttpCacheQueryNfRsp, common.HttpMCDiscovery),
		FsmId:     req.SenderId,
		Ipaddress: make([]*cachemsg.IpAddress, 0, 0),
	}

	instId := (uint64(req.Header.ServiceId) << 32) + uint64(req.Header.SrcMid)
	d.encodeQueryNfRsp(req.InstanceId, queryRsp)
	sdrapi.SendSdrMsgByInstance(queryRsp, instId, topic.TopicDdfCacheQueryNfResponse)
}
func (d *QueryDomainSet) encodeQueryNfRsp(nfInstanceId string, queryRsp *cachemsg.CacheQueryNfResponse) bool {
	instanceID, present := nfidmapmgmt.GetIdValueFromNfInstanceId(nfInstanceId)
	if !present {
		logapi.Error("get instanceid failed")
		return false
	}

	serviceTbls := d.QueryServiceWithNFId(instanceID)
	for _, serviceTbl := range serviceTbls {
		if serviceTbl == nil {
			logapi.Error("serviceTbl nil")
			continue
		}

		defaultPort := common.GetPortByScheme(serviceTbl.Schema)
		for _, ipEndPoint := range serviceTbl.IpEndPoints {
			port := ipEndPoint.GetPortWithDefaultPort(defaultPort)
			if port == common.PortInvalid {
				continue
			}
			ipInfo := &cachemsg.IpAddress{IpVer: common.IpTypeBUTT, IpPort: port, IpAddress: ""}
			if len(ipEndPoint.Ipv6Address) != 0 {
				ipInfo.IpVer = common.IpTypeV6
				ipInfo.IpAddress = ipEndPoint.GetIpv6Address()
			} else if len(ipEndPoint.Ipv4Address) != 0 {
				ipInfo.IpVer = common.IpTypeV4
				ipInfo.IpAddress = ipEndPoint.GetIpv4Address()
			}
			queryRsp.Ipaddress = append(queryRsp.Ipaddress, ipInfo)
		}
	}
	return true
}

