func (d *plyTransponder) handleNextPlyCfgMsg(msg *dmlnkmgrmsg.DmLnkPlyCfgMsg) {
	acslog.Info(" rec nextply cfg msg: %+v", msg)
	if msg == nil || len(msg.LnkPlyCfg) == 0 {
		acslog.Error("msg is invalid")
		return
	}
	inst := sdrapi.MergeUint32ToUint64(msg.Header.SrcMid, msg.Header.ServiceId)
	d.pidToInstId[msg.Header.SrcPid] = inst

	// PID到实例类型和LB策略下一跳的映射
	type InstLb struct {
		inst      uint32
		lbPlyType cslbplytype.LbPlyType
	}
	pidToTypeMapping := map[uint32]InstLb{
		sdrapi.PidScpm:  {sdrapi.InstHlb, cslbplytype.LbHlbNextPly},
		sdrapi.PidDram:  {sdrapi.InstDlb, cslbplytype.LbDlbNextPly},
		sdrapi.PidSeppm: {sdrapi.InstHlb, cslbplytype.LbSeppmNextPly},
		sdrapi.PidDcu:   {sdrapi.InstBsg, cslbplytype.LbBsgNextPly},
		sdrapi.PidSfm:   {sdrapi.InstSflb, cslbplytype.LbSflbNextPly},
	}

	var instType uint32
	var lbPlyType cslbplytype.LbPlyType
	if instLbPly, ok := pidToTypeMapping[msg.Header.SrcPid]; ok {
		instType = instLbPly.inst
		lbPlyType = instLbPly.lbPlyType
	} else {
		acslog.Error("invalid message type[%v]", msg.Header.MessageType)
		return
	}

	interMsg := &cslbpolicy.BatNextLbPly{
		OprType:   outermsg.OprType(msg.LnkPlyCfg[0].OprType),
		SeqId:     msg.AppCtxId,
		Inst:      instType,
		PolicyId:  0, // createBatLnkNextPolicyMsg 函数中根据Inst直接填写
		NextHopId: msg.LnkPlyCfg[0].NextGroupId,
		Ply:       make([]interface{}, 0, len(msg.LnkPlyCfg)),
	}
	for _, policy := range msg.LnkPlyCfg {
		lnkNextPlyCfgItem := &cslbpolicy.LnkNextPlyCfgItem{
			IP:         policy.LocalIp,
			Port:       uint16(policy.LocalPort),
			IPVer:      uint8(policy.IpVersion),
			PeerIP:     policy.PeerIp,
			PeerPort:   uint16(policy.PeerPort),
			ProtocolNo: policy.ProtocolNo,
			TokenId:    policy.TokenId,
		}
		interMsg.Ply = append(interMsg.Ply, lnkNextPlyCfgItem)
	}
	acslog.Info("interMsg: %+v", interMsg)
	plyqueuemgr.EnQueue(&plyqueuemgr.PlyInfo{PlyType: lbPlyType, PlyMsg: interMsg})
}
