func (d *DiscOcsIgnoreOcsLinkDecider) getRecoverTopoReqInterval() int64 {
	var interval int64 = gconst.DefaultRecoverTopoReqInterval

	result, err := omcmcfg.MmlCfgCache().Query(d.GetOmcmCfger(), agfcmgo.ClassCCPTIMER,
		agfcmgo.AGFTID_TYPERECOVERTOPOREQ)
	if err != nil {
		d.GetLogger().Error("get ccptimer failed: %s", err.Error())
		return interval
	}
	timer, ok := result.(*agfcmgo.CCPTIMER)
	if !ok {
		d.GetLogger().Error("convert ccptimer failed")
		return interval
	}

	return int64(timer.VALUE)
}
func (d *DiscOcsIgnoreOcsLinkDecider) IsDuringDiscCustomTimer() bool {
	lastDiscCustomTime := d.GetChgContext().Session().LastDiscCustomTime()
	if d.GetChgContext().Session().LastDiscCustomTime() == 0 {
		return false
	}

	interval := d.getRecoverTopoReqInterval()
	d.GetLogger().Info("recover topo req interval: %d", interval)
	currentTime := perftime.Now().Unix()
	if currentTime-lastDiscCustomTime < interval {
		d.GetLogger().Info("during DiscCustom timer, no need to discover OCS ignore OCS link, current: %d, "+
			"last time: %d", currentTime, lastDiscCustomTime)
		return true
	}

	return false
}

