func NewMsgFromDs(chgDataRef string, msg *sdrmsg.MsgStructV2, plat api.Plat, options ...MsgFromDsOption) *innermsg.MsgFromDS {
	ds2DoMsg := dstodomsg.ConvertSdrMsg2Ds2DoMsg(msg, DefaultToken)
	event := transdsl.NewEvent(ds2DoMsg.GetEventId(), ds2DoMsg)
	msgFromDs := &innermsg.MsgFromDS{ServiceMsg: event, Token: DefaultToken}
	msgFromDs.ChargingDataRef = chgDataRef
	msgFromDs.DoIndex = DefaultDoIndex

	httpMsgField := GetHttpMsgField(msg, msgFromDs.ChargingDataRef)
	if httpMsgField != nil {
		msgFromDs.RspField = httpMsgField.RspField
		msgFromDs.ReqField = httpMsgField.ReqField
		if httpMsgField.DsReqField != nil {
			httpMsgField.DsReqField.ChargingDataRef = chgDataRef
		}
	}
	// 获取http消息失败则直接返回
	httpMsg := getHttpByDs2DoMsg(ds2DoMsg)
	if httpMsg == nil {
		for _, option := range options {
			option(msgFromDs)
		}
		return msgFromDs
	}

	AuditSessionDeal(httpMsgField, httpMsg)

	if localChgSession, duration := LocalChgSessionOf(httpMsg, plat, httpMsgField); localChgSession != nil {
		newSession := session.NewSession(httpMsg, httpMsgField) // 从根据消息生成新的Session因为Session的一些字段本地表没有
		newSession.ChargingDataRef = chgDataRef                 // Alpha框架中ChargingDataRef直接赋值
		newSession.UpdateByLocalChgSession(localChgSession)
		localChgSession.LastInvocationSequenceNumber = int32(newSession.InvocationSequenceNumber)
		StoreLocalChgSession(localChgSession, httpMsg, newSession.InvocationTimeStamp, plat)
		msgFromDs.Session = newSession // Do事务流程直接用到dbSession的数据，DbSession的数据在分发消息前会根据LocalChgSession更新
		msgFromDs.Duration = duration
		msgFromDs.LocalChgSession = localChgSession
		msgFromDs.CongestSCtx = congestion.NewSessionCtx(congestion.SCtxData(localChgSession.CongestStatus))
	}
	// Ds接收到该消息的时间赋值
	msgFromDs.ProcessStartTimestamp = uint64(time.Now().UnixNano() / int64(time.Millisecond))

	for _, option := range options {
		option(msgFromDs)
	}
	return msgFromDs
}
func NewMsgFromDs4SMSF(msg *sdrmsg.MsgStructV2, plat api.Plat, options ...MsgFromDsOption) *innermsg.MsgFromDS {
	ds2DoMsg := dstodomsg.ConvertSdrMsg2Ds2DoMsg(msg, DefaultToken)
	event := transdsl.NewEvent(ds2DoMsg.GetEventId(), ds2DoMsg)
	msgFromDs := &innermsg.MsgFromDS{ServiceMsg: event, Token: DefaultToken, ChargingDataRef: dstodomsg.GetChgRefFormSdrRefCreate(msg)}
	msgFromDs.DoIndex = DefaultDoIndex

	// 获取http消息失败则直接返回
	httpMsg := getHttpByDs2DoMsg(ds2DoMsg)
	if httpMsg == nil {
		for _, option := range options {
			option(msgFromDs)
		}
		return msgFromDs
	}

	// Ds接收到该消息的时间赋值
	msgFromDs.ProcessStartTimestamp = uint64(time.Now().UnixNano() / int64(time.Millisecond))

	for _, option := range options {
		option(msgFromDs)
	}
	return msgFromDs
}
func DoIndex(idx uint32) MsgFromDsOption {
	return func(m *innermsg.MsgFromDS) {
		m.DoIndex = idx
	}
}
func HttpRspContextId(ctxId int64) MsgFromDsOption {
	return func(m *innermsg.MsgFromDS) {
		event, ok := m.ServiceMsg.(transdsl.Event)
		if !ok {
			return
		}
		ds2DoMsg, ok := event.GetMessage().(Ds2DoMsg)
		if !ok {
			return
		}
		sdrMsg := ds2DoMsg.GetSdrMsg()
		httpMsg, ok := sdrMsg.PayLoad.(*httpmsg.Message)
		if !ok {
			return
		}
		rspProp := httpMsg.GetHeader().GetRecvRspProp()
		if rspProp == nil {
			return
		}
		rspProp.ContextId = ctxId
	}
}

