func AuditSessionDeal(httpMsgField *json.HttpMsgField, msg *httpmsg.Message) {
	switch msg.Body.(type) {
	case *nchf.ChargingDataRefCreateParameters:
		// 不带Ref的请求消息在流程结束后处理
		AddtheAuditSessionPool(httpMsgField)
	case *nchf.ChargingDataUpdateParameters, *nchf.ChargingDataReleaseParameters:
		AddtheAuditSessionVolume(httpMsgField)
	default:
		// 如果是回放消息，则尝试清除审计消息表中对应的该审计消息
		if isFailureChgReq := chgmsg.IsFailureChgDataReq(msg); isFailureChgReq {
			auditing.AuditInformation().ClearSession(httpMsgField.ChargingDataRef)
			return
		}
		return
	}
}
func AddtheAuditSessionPool(httpMsgField *json.HttpMsgField) {
	// 审计消息标识字段不为true，不加入审计消息池
	if httpMsgField.ReqField.SamplingAuditFlag != true {
		return
	}
	sessionTime, _ := util.GetTimestampAndTimeZoneOffset(httpMsgField.InvocationTimeStamp)
	auditing.AuditInformation().AddSession(httpMsgField.ChargingDataRef, sessionTime)
}
func AddtheAuditSessionVolume(httpMsgField *json.HttpMsgField) {

	// 判断是否为审计会话消息
	if _, exists := audit.AuditinformationMap[httpMsgField.ChargingDataRef]; !exists {
		return
	}

	auditing.AuditInformation().AddSessionVolume(httpMsgField)
}
func GetHttpMsgField(msg *sdrmsg.MsgStructV2, chargingRef string) *json.HttpMsgField {
	httpMsg := chgmsg.GetHttpMsgFromSdrMsg(msg)
	if httpMsg == nil {
		return nil
	}
	// 审计会话特殊处理
	if _, exist := audit.AuditinformationMap[chargingRef]; exist {
		httpMsgFieldReq, err := chgmsg.GetReqFieldFromHttpMsg(httpMsg)
		if err == nil {
			return httpMsgFieldReq
		}
	}
	httpMsgFieldRsp, err := chgmsg.GetReqFieldFromHttpMsg(httpMsg)
	if err == nil {
		return httpMsgFieldRsp
	}
	return nil
}
func getChgRef(chgReq interface{}) string {
	if msg, ok := chgReq.(chgmsg.ChargingDataRefReqParameters); ok {
		return msg.GetChargingDataRef()
	}
	return ""
}

