func (e *extension) GetReceiverMiddleware() actor.ReceiverMiddleware {
	middleware := func(next actor.ReceiverFunc) actor.ReceiverFunc {
		fn := func(rc actor.ReceiverContext, envelope *actor.MessageEnvelope) {
			c, ok := rc.(actor.Context)
			if !ok {
				logapi.Error("extension get actor context failed")
				return
			}
			switch msg := envelope.Message.(type) {
			case *actor.Started:
				e.localInit(c)
				next(c, envelope)
			case *actor.Restarting:
				next(c, envelope)
			case *actor.Stopped:
				next(c, envelope)
			case registry.PhaseChanged:
				e.onPhaseChanged(&msg)
				next(c, envelope) // 业务使用了这个消息需要传递下去
			case *timeOut:
				e.onTimeOutMsg(msg)
			case *interval:
				e.onIntervalMsg(msg)
			case *sdrply.CheckTokenPly:
				e.onCheckTokenPly(msg)
			default:
				// 处理启动后的消息
				e.msgProcAfterStarted(next, rc, envelope)
			}
		}
		return fn
	}
	return middleware
}
