func (m *mmlLocalOcsIp) queryOmcm(cfgDataItf omcm.CfgDataItf, param LocalOcsIpQueryParam) (interface{}, error) {
	condition := cfgDataItf.NewCondition()
	switch param.IpType {
	case cm_go.AGFIP_TYPEIPV4:
		err := condition.AddCondition(cm_go.FieldLOCALOCSIPIPV4ADDRESS, omcm.OperateEqual, net.ParseIP(param.Ip))
		if err != nil {
			return false, err
		}
	case cm_go.AGFIP_TYPEIPV6:
		err := condition.AddCondition(cm_go.FieldLOCALOCSIPIPV6ADDRESS, omcm.OperateEqual, net.ParseIP(param.Ip))
		if err != nil {
			return false, err
		}
	default:
		return false, fmt.Errorf("invalid LOCALOCSIP query param %+v", param)
	}
	result, err := cfgDataItf.SelectFirstByCondition(cm_go.ClassLOCALOCSIP, condition, nil)
	if err != nil || result == nil {
		// 如果没找到，也要更新缓存，避免此IP后续查找OMCM
		m.localOcs.Store(param.Ip, false)
		return false, fmt.Errorf("LOCALOCSIP of param %+v not found", param)
