	ocs, ok := result.(*cm_go.LOCALOCSIP)
	if !ok {
		return false, fmt.Errorf("query result %T from omcm is not *cm_go.LOCALOCSIP", result)
	}
	// 查询成功后需要更新缓存
	m.updateCache(ocs, true)
	return true, nil
}
