func (d *AgfDomainSet) isNotifyFromCdf(msg *sdrmsg.MsgStructV2) bool {
	if cdfNotify, ok := msg.PayLoad.(*cdfmsg.CdfStatusNotifyMsg); cdfNotify != nil && ok {
		watcher.CdfStatusWatcherSingleton.SetCdfStatusFromCdfMsg(cdfNotify.GetCdfStatus())
		metrics.Manager.CdfMsg.CdfStatusNotify.Inc()
		metrics.Manager.CdfMsg.TotalCdfStatusNotify.Inc()
		return true
	}
	return false
}
func (d *AgfDomainSet) handleSdrMsg(msg *sdrmsg.MsgStructV2) {
	if d.isNotifyFromCdf(msg) {
		return
	}

	d.delayMetric.DsHandleSdrMsgStart()
	defer d.delayMetric.DsHandleSdrMsgEnd()
	metrics.Manager.DsMsg.AddRecvSdrMsg()
	d.tpsReporter.CountChargingReqMsg(msg)

	if d.shouldRejectMsg(msg) {
		return
	}

	domainObj, msgFromDs, err := d.doManager.MsgDispatch(msg)
	if domainObj == nil || msgFromDs == nil || err != nil {
		// 处理HTTP请求申请Do失败
		d.handleDoAllocFailed(msg)
		metrics.Manager.DsMsg.AddDropSdrMsg()
		return
	}

	// 如果短消息场景，则直接转发给do处理
	if d.isShortMsgStage(msg) {
		//  短消息计费请求需要发给CDF，使用chyargingDataRef做hash，所以需要获取chgRef
		msgFromDs.ChargingDataRef = dstodomsg.GetChgRefFormSdrRefCreate(msg)
		domainObj.Send(msgFromDs)
		metrics.Manager.DsMsg.AddSendSdrMsg()
		return
	}

	httpMsgField := chgmsg.GetHttpMsgField(msg)
	if httpMsgField != nil {
		msgFromDs.ReqField = httpMsgField.ReqField
		msgFromDs.RspField = httpMsgField.RspField
	}

	// 如果不是http请求消息，直接转发给do处理
	httpMsg := getHttpReqByMsgFromDS(msgFromDs)
	if httpMsg == nil {
		domainObj.Send(msgFromDs)
		metrics.Manager.DsMsg.AddSendSdrMsg()
		return
	}

	// 审计消息处理
	d.AuditSessionHander(httpMsgField, httpMsg)

	// 只有当消息是create、update、release、notify四种InitialMsg请求消息时，session才不为nil
	// 其他非InitialMsg请求消息无需更新session、duration、diff
	if localChgSession, duration := d.localSessionOf(httpMsg, httpMsgField); localChgSession != nil {
		// 从根据消息生成新的Session因为Session的一些字段本地表没有, 包括ChargingDataRef得从消息生成
		newSession := NewSession(httpMsg, httpMsgField)
		newSession.UpdateByLocalChgSession(localChgSession)
		localChgSession.LastInvocationSequenceNumber = int32(newSession.InvocationSequenceNumber)
		d.storeLocalChgSession(localChgSession, httpMsg, newSession.InvocationTimeStamp)
		msgFromDs.Duration = duration
		msgFromDs.Session = newSession
		msgFromDs.LocalChgSession = localChgSession
		msgFromDs.CongestSCtx = congestion.NewSessionCtx(congestion.SCtxData(localChgSession.CongestStatus))
		msgFromDs.ChargingDataRef = newSession.ChargingDataRef
	}
	domainObj.Send(msgFromDs)
	metrics.Manager.DsMsg.AddSendSdrMsg()
}
func (d *AgfDomainSet) localSessionOf(httpMsg *httpmsg.Message, httpMsgField *json.HttpMsgField) (*dbadpater.LocalChgSession, int64) {
	// 如果是Notify消息，不用查数据库
	if _, ok := httpMsg.Body.(*nchf.ChargingDataNotifyParameters); ok {
		localChgSession := &dbadpater.LocalChgSession{}
		return localChgSession, 0
	}

	_, ok := httpMsg.Body.(chgmsg.ChargingDataReqParameters)
	if !ok {
		return nil, 0
	}

	// http消息中请求字段为空，不是请求消息，返回
	if !httpMsgField.IsAllReqFieldValid() {
		return nil, 0
	}

	// 如果是update和release消息，则会话已经存在ddf，更新会话数据返回即可
	sessionKey := GetSessionKeyByChgReq(httpMsgField)

	// 如果软参值为0且是QBC场景，则使用ChargingDataRef作为key值
	if softpara.Ncg().DwValueOf(softpara.QbcIsUseChgDataRef) == softpara.QbcUseChgDataRef && d.IsQbcChgScene(httpMsgField.ReqField) {
		d.WriteNfLog(nflog.Info, "Dword22_BIt29 is 0 && isQbcChgScene, set ChargingDataRef as sessionKey")
		sessionKey = httpMsgField.ChargingDataRef
	}

	localChgSession, err := d.QueryLocalChgSession(sessionKey)
	if localChgSession == nil || err != nil {
		localChgSession = d.QueryLocalChgSessionByOldKeyAndDeleteDdf(sessionKey, httpMsgField)
	}

	// 若本地表为空则新生成一个返回去
	if localChgSession == nil {
		newLocalChgSession := dbadpater.GenerateLocalChgSessionByChargingDataRequest(sessionKey,
			httpMsgField.InvocationSequenceNumber, httpMsgField.InvocationTimeStamp)
		duration := LocalDurationOf(httpMsgField, newLocalChgSession)
		return newLocalChgSession, duration
	}

	duration := LocalDurationOf(httpMsgField, localChgSession)

	return localChgSession, duration
}
func (d *AgfDomainSet) AuditSessionHander(httpMsgField *json.HttpMsgField, msg *httpmsg.Message) {
	switch msg.Body.(type) {
	case *nchf.ChargingDataRefCreateParameters:
		// 不带Ref的请求消息在流程结束后处理
		d.IfAddtheAuditSessionPool(httpMsgField)
	case *nchf.ChargingDataUpdateParameters, *nchf.ChargingDataReleaseParameters:
		d.IfAddtheAuditSessionVolume(httpMsgField)
	default:
		// 如果是回放消息，则尝试清除审计消息表中对应的该审计消息
		if isFailureChgReq := chgmsg.IsFailureChgDataReq(msg); isFailureChgReq {
			metrics.Manager.Audit.FailureMsg.Inc()
			metrics.Manager.Audit.TotalFailureMsg.Inc()
			auditing.AuditInformation().ClearSession(httpMsgField.ChargingDataRef)
			return
		}
		return
	}
}
func (d *AgfDomainSet) IfAddtheAuditSessionPool(httpMsgField *json.HttpMsgField) {
	// 审计消息标识字段不为true，不加入审计消息池
	if httpMsgField.ReqField.SamplingAuditFlag != true {
		return
	}
	sessionTime, _ := util.GetTimestampAndTimeZoneOffset(httpMsgField.InvocationTimeStamp)
	auditing.AuditInformation().AddSession(httpMsgField.ChargingDataRef, sessionTime)
}

