func (d *AgfDomainSet) QueryLocalChgSessionByOldKeyAndDeleteDdf(sessionkey string, httpMsgField *json.HttpMsgField) *dbadpater.LocalChgSession {
	// 当数据库中本地表和远端表都没有查到会话记录，修改key值进行查询
	// Dword23_BIt26软参值为0，不进行后续流程
	if softpara.Ncg().DwValueOf(softpara.IsChangeSessionkeyQuery) != softpara.ChangeSessionkeyExec {
		d.WriteNfLog(nflog.Info, "Dword23_BIt26 is 0, stopping subsequent operations")
		return nil
	}

	sessiontime := time.Now().UnixNano()
	// 如果超出预设时间，停止后续操作
	if sessionkeyrecord.SessionKeyGet().GetChangeTime() == 0 {
		d.WriteNfLog(nflog.Info, "the session_time overstep the pre-set time, the record time is 0")
		return nil
	}

	if isOverTime := d.IsNeedAgingBySessionTime(sessiontime); isOverTime == true {
		sessionkeyrecord.SessionKeyGet().SetChangeTime(0)
		d.WriteNfLog(nflog.Info, "the session_time overstep the pre-set time")
		return nil
	}

	// 记录修改前后的key值，用以后续的删除和更新数据库内容
	var oldsessionkey string
	oldkeymodel := sessionkeyrecord.SessionKeyGet().GetOldKeyModel()
	if oldsessionkey = d.GetOldSessionkey(oldkeymodel, httpMsgField); oldsessionkey == "" {
		return nil
	}

	oldlocalChgSession, _ := d.QueryLocalChgSession(oldsessionkey)
	// 删除本地数据库和远端数据库中对应记录
	if oldlocalChgSession != nil {
		if deleteerr := d.DeleteChgSession(oldlocalChgSession); deleteerr != nil {
			d.WriteNfLog(nflog.Info, "Delete oldkey local chg session failed error: %s.", deleteerr)
		}
		remoteChgSession, _ := d.QueryRemoteChgSessionBySessionKey(oldlocalChgSession.SessionKey)
		if remoteChgSession != nil {
			if deleteerr := d.DeleteChgSession(remoteChgSession); deleteerr != nil {
				d.WriteNfLog(nflog.Info, "Delete oldkey remote chg session failed error: %s.", deleteerr)
			}
		}
		oldlocalChgSession.SessionKey = sessionkey
		// key值切换后，首消息按照原有逻辑更新远端表
		oldlocalChgSession.LastUpdateTime = 0
		return oldlocalChgSession
	}
	return nil
}
func (d *AgfDomainSet) GetOldSessionkey(oldkeymodel map[string]uint32, httpMsgField *json.HttpMsgField) string {
	sessionkey := ""
	if oldkeymodel == nil {
		d.WriteNfLog(nflog.Error, "Get old sessionkey failed, the oldkeymodel is nil")
		return sessionkey
	}
	if !httpMsgField.IsAllReqFieldValid() {
		return sessionkey
	}

	chargingId := httpMsgField.ChargingId
	supi := httpMsgField.SubscriberIdentifier

	if supi == "" || chargingId == 0 {
		sessionkey = httpMsgField.ChargingDataRef
	} else {
		sessionkey = dbadpater.GetSessionKeyBySupiAndChargingId(supi, chargingId)
	}

	if oldkeymodel[sessionkeyrecord.UseChargingDataRefAsSessionKey] == 1 {
		sessionkey = httpMsgField.ChargingDataRef
	}

	if oldkeymodel[sessionkeyrecord.SessionKeyAddPdusessionId] == 1 {
		sessionkey = sessionkey + strconv.FormatInt(httpMsgField.PdusessionId, gconst.FormatBase10)
	}

	// 如果软参值为0且是QBC场景，则使用ChargingDataRef作为key值
	if oldkeymodel[sessionkeyrecord.QbcIsUseChgDataRef] == 0 && d.IsQbcChgScene(httpMsgField.ReqField) {
		sessionkey = httpMsgField.ChargingDataRef
	}

	d.WriteNfLog(nflog.Info, "get the old sessionkey: %s", sessionkey)
	return sessionkey
}
func (d *AgfDomainSet) QueryLocalChgSession(sessionKey string) (*dbadpater.LocalChgSession, nferr.NfError) {
	// 对于ChargingDataRef为空且不由CHF生成ChargingDataRef的请求，将该消息传给DO，在DO处直接返回201，不走事务流程
	if sessionKey == "" {
		d.WriteNfLog(nflog.Info, "initial msg has an empty session key")
		return nil, nferr.New("DbProxy", "QueryLocalChgSession", "SessionKey is empty , no need query session")
	}
	// 在本地表查询到数据，使用本地表数据返回
	if localChgSession, err := d.QueryLocalChgSessionBySessionKey(sessionKey); localChgSession != nil {
		return localChgSession.Clone(), err
	}

	// 若本地表查不到则查远端表，先根据消息生成新的本地表，然后用远端表更新本地表后返回
	remoteChgSession, err := d.QueryRemoteChgSessionBySessionKey(sessionKey)
	if remoteChgSession != nil {
		// 用远端表更新本地表
		localChgSession := &dbadpater.LocalChgSession{}
		localChgSession.UpdateByRemoteChgSession(remoteChgSession)

		return localChgSession, err
	}
	return nil, err
}
func (d *AgfDomainSet) storeLocalChgSession(localChgSession *dbadpater.LocalChgSession, msg *httpmsg.Message, invocationTimeStamp uint32) {
	// 将本地表中LastInvocationTimeStamp赋值为本条消息的时间戳
	localChgSession.LastInvocationTimeStamp = invocationTimeStamp

	// 不修正duration可以直接返回
	if softpara.Ncg().DwValueOf(softpara.DurationPolicyKey) != softpara.DurationUseDb {
		return
	}

	// ChargingDataCreateParameters不需要插入数据库
	if _, ok := msg.GetBody().(*nchf.ChargingDataCreateParameters); ok {
		d.WriteNfLog(nflog.Info, "no chargingDataRef create do not InsertChgSession")
		return
	}

	// ChargingDataRefCreateParameters需要插入数据库
	if _, ok := msg.GetBody().(*nchf.ChargingDataRefCreateParameters); ok {
		if err := d.InsertChgSession(localChgSession); err != nil {
			d.ErrorNfLog("insert local chg session failed, error: %s.", err.Error())
			return
		}
		d.WriteNfLog(nflog.Info, "insert local chg session {%s} in ds success",
			util.AnonymizationOf(localChgSession.SessionKey))
		return
	}

	err := d.UpdateChgSession(localChgSession)
	if err == nil {
		// 更新成功则直接返回，更新失败则后续重插入一次
		d.WriteNfLog(nflog.Info, "update local chg session {%s} in ds success",
			util.AnonymizationOf(localChgSession.SessionKey))
		return
	}

	// 更新失败可能是因为当前数据库中没有该记录，说明Create消息的会话信息没存到数据库里
	// 为了增加可靠性，这种情况下，尝试将Update消息的会话信息插入到数据库中，避免后续流程混乱
	d.WriteNfLog(nflog.Warning, "charging update request update local chg session failed, try to insert session, err: %s", err.Error())
	if err := d.InsertChgSession(localChgSession); err != nil {
		d.ErrorNfLog("charging update request insert local chg session failed, error: %s.", err.Error())
		return
	}
	d.WriteNfLog(nflog.Info, "update local chg session {%s} in ds success",
		util.AnonymizationOf(localChgSession.SessionKey))
}
func (d *AgfDomainSet) handleDoAllocFailed(sdrMsg *sdrmsg.MsgStructV2) {
	httpReq := chgmsg.GetHttpMsgFromSdrMsg(sdrMsg)
	if httpReq == nil {
		return
	}
	var rsp *httpmsg.Message
	var isFailureChgReq bool
	if isFailureChgReq = chgmsg.IsFailureChgDataReq(httpReq); isFailureChgReq {
		rsp = chgmsg.HttpErrRspOf(httpReq, gconst.HttpCode429TooManyRequests, "Agf is overload")
	} else {
		rsp = chgmsg.HttpErrRspOf(httpReq, gconst.HttpCode503ServiceUnavailable, "Agf is overload")
	}
	if rsp == nil {
		return
	}
	if err := d.SendHttpResponseMsg(httpReq.Header, rsp); err != nil {
		d.ErrorNfLog("Send overflow response to HTTP failed, error: %s", err.Error())
		return
	}
	if !isFailureChgReq {
		d.addPerfBy503Rsp(httpReq)
	} else {
		d.addPerfBy429Rsp(httpReq)
	}
	d.AddPerfProcessOfSMSF503429Rsp(isFailureChgReq)
}

