func (m *mmlCcpRcact) queryCache(param RcactQueryParam) (interface{}, bool) {
	switch param.RcType {
	case cm_go.AGFRC_TYPEDEFAULT:
		if defaultAct := m.defaultAct.Load(); isValidRcact(defaultAct) {
			return defaultAct, true
		}
		return nil, false
	case cm_go.AGFRC_TYPETIMEOUT:
		if timeoutAct := m.timeoutAct.Load(); isValidRcact(timeoutAct) {
			return timeoutAct, true
		}
		return nil, false
	case cm_go.AGFRC_TYPELINKFAULT:
		if linkFault := m.linkFault.Load(); isValidRcact(linkFault) {
			return linkFault, true
		}
	case cm_go.AGFRC_TYPEVALUE:
		rcact, ok := m.codeTypeAct.Load(param.CodeType)
		return rcact, ok
	default:
		return nil, false
	}
	return nil, false
}
func (m *mmlCcpRcact) queryOmcm(cfgDataItf omcm.CfgDataItf, param RcactQueryParam) (interface{}, error) {
	condition := cfgDataItf.NewCondition()
	if err := condition.AddCondition(cm_go.FieldCCPRCACTRCTYPE, omcm.OperateEqual, param.RcType); err != nil {
		return nil, fmt.Errorf("mmlCcpRcact query failed, add condition error: %v", err)
	}
	// 如果是按照响应码方式查询RCACT，则再添加添加对应条件
	if param.RcType == cm_go.AGFRC_TYPEVALUE && param.CodeType != 0 {
		if err := condition.AddCondition(cm_go.FieldCCPRCACTCODETYPE, omcm.OperateEqual, param.CodeType); err != nil {
			return nil, fmt.Errorf("mmlCcpRcact query failed, add condition error: %v", err)
		}
	}
	result, err := cfgDataItf.SelectFirstByCondition(cm_go.ClassCCPRCACT, condition, nil)
	if err != nil {
		return m.queryDefaultRcact(cfgDataItf, param)
	}
	rcact, ok := result.(*cm_go.CCPRCACT)
	if ok {
		// 如果查询成功，则更新缓存，并返回
		m.updateCache(rcact, param)
		return rcact, nil
	}
	// 查询失败则尝试获取default配置
	return m.queryDefaultRcact(cfgDataItf, param)
}
func (m *mmlCcpRcact) queryDefaultRcact(cfgDataItf omcm.CfgDataItf, param RcactQueryParam) (interface{}, error) {
	// default配置对2xx/400/403/404不生效
	if util.IsPassThroughCode(int32(param.CodeType)) {
		m.updateCache(invalidRcact, param)
		return nil, errors.New("code type not config rcact")
	}
	// 如果缓存存在，则直接返回
	if defaultAct := m.defaultAct.Load(); defaultAct != nil && defaultAct != invalidRcact {
		m.updateCache(defaultAct.(*cm_go.CCPRCACT), param)
		return defaultAct, nil
	}
	condition := cfgDataItf.NewCondition()
	if err := condition.AddCondition(cm_go.FieldCCPRCACTRCTYPE, omcm.OperateEqual, cm_go.AGFRC_TYPEDEFAULT); err != nil {
		// 如果没找到记录，则也要更新缓存，避免像200这种响应码每次都从OMCM中查找
		m.updateCache(invalidRcact, param)
		return nil, fmt.Errorf("mmlCcpRcact query default rcact failed, add condition error %v", err)
	}
	result, err := cfgDataItf.SelectFirstByCondition(cm_go.ClassCCPRCACT, condition, nil)
	if err != nil {
		// 如果没找到记录，则也要更新缓存，避免像200这种响应码每次都从OMCM中查找
		m.updateCache(invalidRcact, param)
		return nil, fmt.Errorf("mmlCcpRcact query default rcact failed, select first by condition error %v", err)
	}
	rcact, ok := result.(*cm_go.CCPRCACT)
	if !ok {
		// 如果没找到记录，则也要更新缓存，避免像200这种响应码每次都从OMCM中查找
		m.updateCache(invalidRcact, param)
		return nil, fmt.Errorf("mmlCcpRcact query default rcact failed, result %T is not *cm_go.CCPRCACT type", result)
	}
	// 查询默认配置成功则更新缓存
	m.defaultAct.Store(rcact)
	return rcact, nil
}
func (m *mmlCcpRcact) updateCache(rcact *cm_go.CCPRCACT, param RcactQueryParam) {
	switch param.RcType {
	case cm_go.AGFRC_TYPEDEFAULT:
		m.defaultAct.Store(rcact)
	case cm_go.AGFRC_TYPETIMEOUT:
		m.timeoutAct.Store(rcact)
	case cm_go.AGFRC_TYPELINKFAULT:
		m.linkFault.Store(rcact)
	case cm_go.AGFRC_TYPEVALUE:
		if param.CodeType != 0 {
			m.codeTypeAct.Store(param.CodeType, rcact)
		}
	default:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "No need to update cache for an invalid rc type %v.", param.RcType)
	}
}
func buildMmlCcpRcact() *mmlCcpRcact {
	return &mmlCcpRcact{
		defaultAct:  &atomic.Value{},
		timeoutAct:  &atomic.Value{},
		linkFault:   &atomic.Value{},
		codeTypeAct: &sync.Map{},
	}
}

