func (r *SdrMsgUnmarshalExtension) GetReceiverMiddleware() actor.ReceiverMiddleware {
	return func(next actor.ReceiverFunc) actor.ReceiverFunc {
		return func(c actor.ReceiverContext, envelope *actor.MessageEnvelope) {
			sdrMsg, ok := envelope.Message.(*sdrmsg.MsgStructV2)
			if ok && sdrMsg != nil {
				nflog.AgfLogger().WriteNfLog(nflog.Info, "Unmarshal msg, Topic=%v, Type=%T", sdrMsg.Topic, sdrMsg.PayLoad)
				unmarshalSdrMsg(sdrMsg)
			}
			next(c, envelope)
		}
	}
}
