func unmarshalSdrMsg(msg *sdrmsg.MsgStructV2) {
	nflog.AgfLogger().WriteNfLog(nflog.Info, "Unmarshal msg, Topic=%v, Type=%T", msg.Topic, msg.PayLoad)
	if bytes, isBytes := msg.PayLoad.([]byte); isBytes {
		if msg.Topic == uint32(sftopic.MsgBetweenHttpAgf) {
			httpBody := &httpmsg.Message{}
			err := httpBody.Unmarshal(bytes)
			if err != nil {
				nflog.AgfLogger().ErrorNfLog("Unmarshal msg failed, Topic=%v, Type=%T", msg.Topic, msg.PayLoad)
				return
			}
			msg.PayLoad = httpBody
		}

	}
}

