func GetAllTokenVersion() []*rules.Versioner_AppTypeWithVersion {
	acslog.Info("GetAllTokenVersion")
	res := []*rules.Versioner_AppTypeWithVersion{}

	tokenPolicyVersion.Range(func(appType, version interface{}) bool {
		var ver int64 // 通过类型判断获取int64类型的version
		switch version.(type) {
		case int64:
			ver = version.(int64)
		case uint64:
			ver = int64(version.(uint64))
		default:
			acslog.Error("invalid version: [%v]", version)
			return true
		}
		data := rules.Versioner_AppTypeWithVersion{
			AppType: appType.(uint32),
			Version: ver,
		}
		res = append(res, &data)
		return true
	})

