func (serviceDo *object) handleNfListQueryRsp(qryNfType nnrf29510.NFType, msg *httpnnrf29510.GetNFInstancesResponses, isDoubleBrokenChain uint32) bool {
	logapi.Info("handleNfListQueryRsp[%v] qryNfType[%v]", msg, qryNfType)
	if msg.StatusCode != gconst.StatusCodeOk {
		logapi.Error("[Inner Interface Message Trace] query nf list fail[%v][%v]!", msg.StatusCode, msg.ProblemDetails)
		return false
	}
	if msg.GetNFInstanceRespData == nil {
		logapi.Error("[Inner Interface Message Trace] GetNFInstanceRespData is nil! nfType[%v]", qryNfType)
		nrfnfquery.StartWorkMgrInst().UpdateNfList(httpnnrf29510.NFType(qryNfType), []string{})
		// nflist查询结果为空时删除对应nf类型的nf
		serviceDo.sendNFListRetrievalDeleteData(0, qryNfType, true)
		return false
	}
	selfLink := serviceDo.getSelfLink(msg)
	if len(selfLink) == 0 {
		logapi.Warning("[Inner Interface Message Trace] self link is invalid! nfType[%v]", qryNfType)
		nrfnfquery.StartWorkMgrInst().UpdateNfList(httpnnrf29510.NFType(qryNfType), []string{})
		// nflist查询结果为空时删除对应nf类型的nf
		serviceDo.sendNFListRetrievalDeleteData(0, qryNfType, true)
		return false
	}
	nfType := serviceDo.getNfTypeWithSelfLink(selfLink)
	if nfType == int32(httpnnrf29510.NFTypeINVALID) {
		logapi.Error("[Inner Interface Message Trace] nfType invalid!")
		return false
	}
	itemLinks := serviceDo.getItemLinks(msg)
	if itemLinks == nil {
		logapi.Error("[Inner Interface Message Trace] item links is nil!")
		return false
	}

	// 双活故障，记录故障时间，刷新双活状态
	serviceDo.handleNrfDoubleChainStatus(qryNfType, isDoubleBrokenChain)
	serviceDo.addNfListToUpdateQueue(nfType, itemLinks)
	return true
}
func (serviceDo *object) handleInnerUpdateDoubleChainStatusMsg(nfType nnrf29510.NFType, doubleChainStatus uint32) {

	pid, err := serviceDo.GetInsertDoActor(nfType)
	if err != nil {
		logapi.Error("handleInnerUpdateDoubleChainStatusMsg can not get insert do actor, nfType[%v]", nfType)
		return
	}

	recordList := serviceDo.QueryNFWithNFType(nfType)
	for _, v := range recordList {
		// 双活状态一直则不刷新
		if v.DoubleChainStatus == doubleChainStatus {
			continue
		}
		serviceDo.Send(pid, &datatrace.InnerUpdateDoubleChainStatusData{
			NfInstanceID:      v.NfInstanceId,
			NfType:            nfType,
			DoubleChainStatus: doubleChainStatus,
			DataTrace:         serviceDo.setDataTrace(),
		})
	}
}
func (serviceDo *object) handleInnerUpdateNf() {
	if !nrfnfseg.GetColocateSwt() {
		return
	}
	// 双活故障到恢复 11分钟后触发一次全量检索nf
	nfTypeList := nrfnfseg.GetNfTypeList()
	for _, nfType := range nfTypeList {
		recordList := serviceDo.QueryNFWithNFType(nnrf29510.NFType(nfType))
		for _, v := range recordList {
			innerupdate.UpdateQueueInst().Add(nfType, nfidmapmgmt.GetInstanceIdByValue(v.NfInstanceId))
		}
	}
}
func (serviceDo *object) handleNrfDoubleChainStatus(qryNfType nnrf29510.NFType, isDoubleBrokenChain uint32) {
	currentTime := time.Now().Unix()
	// 双活故障，记录故障时间，刷新双活状态
	if isDoubleBrokenChain == common.DoubleChainBroken {
		common.NrfDoubleChain.OldStatus = isDoubleBrokenChain
		common.NrfDoubleChain.FaultTime = currentTime
		serviceDo.handleInnerUpdateDoubleChainStatusMsg(qryNfType, isDoubleBrokenChain)
		return
	}

	// 双活故障到恢复时,11分钟 + 检索周期后刷新NF数据
	if common.NrfDoubleChain.OldStatus == common.DoubleChainBroken &&
		(currentTime-common.NrfDoubleChain.FaultTime) > (common.NrfDbCheckPeriod+int64(nrfnfseg.GetNfListQueryPeriod())) {
		serviceDo.handleInnerUpdateNf()
		// 只触发一次
		common.NrfDoubleChain.OldStatus = isDoubleBrokenChain
	}
}
func (serviceDo *object) isAllowUpdateDoubleChainStatus(isDoubleBrokenChain uint32) bool {
	currentTime := time.Now().Unix()
	// 双活故障到恢复之后，11分钟内不允许修改双活状态
	if isDoubleBrokenChain == common.DoubleChainNormal && currentTime-common.NrfDoubleChain.FaultTime < common.NrfDbCheckPeriod {
		return false
	}
	return true
