	return nil
}
func generateRandPwd() string {
	all := upper + lower + digits + specialChar
	buf := make([]byte, length, length)
	// at least one special character, one digit, one upper case, one lower case
	buf[0] = digits[randInt(len(digits))]
	buf[1] = upper[randInt(len(upper))]
	buf[2] = lower[randInt(len(lower))]
	buf[3] = specialChar[randInt(len(specialChar))]
	for i := 4; i < length; i++ {
		buf[i] = all[randInt(len(all))]
	}
	shuffle(len(buf), func(i, j int) {
		buf[i], buf[j] = buf[j], buf[i]
	})
	str := string(buf)
	return str
}
func randInt(max int) int {
	var n *big.Int
	var err error
	if n, err = rand.Int(rand.Reader, big.NewInt(int64(max))); err != nil {
		return 0
	}
	return int(n.Int64())
