func (s *sdrBaseActor) watchAllMicroService() {
	acslog.Error("%s watchAllMicroService come in[%v]", s.csName, api.WatchServiceList)

	var err error
	for _, svcName := range api.WatchServiceList {
		err = s.CmfWatchCsDetail(svcName)
		if err != nil {
			acslog.Error("CmfWatchCsDetail[%v] fail[%v]!", svcName, err)
			return
		}
		acslog.Error("CmfWatchCsDetail[%v] success!", svcName)
	}
