func renewRulesCheckProc(renew *rules.RulesCheckRequest_Renew) {
	acslog.Info("enter renewRulesCheckProc")
	if renew == nil || renew.ShouldUpdate == nil {
		acslog.Error("renew is nil")
		return
	}
	shouldUpdate := renew.ShouldUpdate

	for _, topicVersion := range shouldUpdate.TopicInfoVersions {
		policyactor.SendToActor(policyactor.TopicActorKey, &policyactor.ResendTopicMsg{TopicId: topicVersion.TopicId})
	}

	for _, routeVersion := range shouldUpdate.AppRouteInfoVersions {
