func (c *Controller) isTakeCongestFlow() (isTake bool, outcome bool) {
	// 异常场景流程结果返回true，避免影响后续流程
	if c.GetChgContext().Session().DbSession() == nil {
		return false, true
	}
	// 关闭拥塞控制功能时，流程结果直接返回true
	if congestion.CtrlSwitch().IsClose() {
		return false, true
	}
	// 隔离所有ocs时，流程结果直接返回false
	if c.isIsolateAllOcs() {
		return false, false
	}
	// 如果开启按照消息间隔进行控制，则直接按照该策略，不走会话级和全局拥塞控制流程
	if c.isSeqCtrlReq() {
