		a.notifyDramResendPly(msg.ResendType)
		a.notifyDcuResendPly(msg.ResendType)
		a.notifyScpmResendPly(msg.ResendType)
		a.notifySeppmResendPly(msg.ResendType)
		a.notifySfmResendPly(msg.ResendType)
	default:
	}
}
func (a *tokenActor) processRsp(msgData *rules.RulePushAck) {
	if msgData.Result != rules.Result_success {
		acslog.Error("[%v] failed.", msgData.Seq)
		return
	}
	tokenPolicyVersion.Range(func(appType, seq interface{}) bool {
		if msgData.Seq == seq {
			acslog.Info("appType [%v] set token success, seq is [%v]", appType, msgData.Seq)
		}
		return true
	})
}
func (a *tokenActor) handleDmTokenMsg(msg *policytransponder.TokenSlice) {
	if msg == nil {
		acslog.Error("msg is nil")
		return
	}

	var tokenDataInfo TokenData
	for _, token := range msg.Tokens {
		if token.OprType == outermsg.OprType_OprTypePost {
			// 新增DLB Token
			dlbStTokenData[token.TokenId] = token.Inst
			tokenDataInfo = TokenData{token.AppType, msg.TokenGroup, token.Inst, token.TokenId, SyncOp}
		} else if token.OprType == outermsg.OprType_OprTypeDelete {
			// 删除DLB Token
			if _, ok := dlbStTokenData[token.TokenId]; ok {
				delete(dlbStTokenData, token.TokenId)
			}
			tokenDataInfo = TokenData{token.AppType, msg.TokenGroup, token.Inst, token.TokenId, BanishOp}
		} else {
			acslog.Error("invalid token operation")
			continue
		}
		a.tokenEnqueue(tokenDataInfo)
	}
}
