func (d *DoInstance) UpdateSmsfCtx(req *msg.Ds2DoReqMsg) error {
	// 更新基础上下文
	// 使用事务ID作为日志key值,由于BaseContext里transId会在Update函数里++,所以此处+1
	currentSessionKey := strconv.FormatUint(uint64(d.BaseContext.TransId())+1, gconst.FormatBase10)
	d.BaseContext.Update(req.DoIndex, currentSessionKey, req.Token)
	if err := d.SdrContext.Update(d.BaseContext.DoIndex(), d.BaseContext.TokenId(), req.ChgDataRef, d.BaseContext.TransId()); err != nil {
		return err
	}
	// 消息流程为CreateProcedure或CreateRefProcedure类型，告警流程为AlmNotifyProcedure
	procedure := context.SmsfProcedureOf(req)
	if procedure == context.InvalidProcedure {
		return errors.New("receive unexpect smsf request type")
	}

	// 根据业务流程分别填充http与cdf消息上下文
	if err := d.updateSpecialContextByProcedure(procedure, req); err != nil {
		return err
	}

	// 赋值接收到请求消息的开始时间，用于AGF处理时延话统统计
	d.PerfReporter.SetMsgReqStartTimeStamp(req.ProcessStartTimestamp)
	d.DoMetricReporter.GetMetricReporter().DelayMetric.ReqChgMsgFromSmf()

	d.ChgContext.Update(&dbadpater.DbSessionInfo{ChargingDataRef: req.ChgDataRef}, nil, procedure, context.SmsfCarrier)
	d.DoMetricReporter.AddChgMsgMetricByChgDataReq()
	d.GetLogger().Info("Procedure is " + context.ChgProcedureName[procedure])
	d.GetDoMetricReporter().ReqFromSmfMetric()

	// 根据请求信息进行话统打点
	d.PerfReporter.AddPerfByChgMsg()

	return nil
}
func (d *DoInstance) updateSpecialContextByProcedure(procedure context.ChgProcedure, req *msg.Ds2DoReqMsg) error {
	switch procedure {
	case context.CreateProcedure, context.CreateRefProcedure:
		// 更新http请求消息上下文
		d.RecvReqHttpContext.UpdateMsg(req.Req)
	case context.AlmNotifyProcedure:
		// 更新cdf上下文中告警通知请求消息上下文
		d.RecvReqAlmNotifyContext.Update(req)
	default:
		nflog.AgfLogger().ErrorNfLog("not expect procedure:%s", context.ChgProcedureName[procedure])
		return errors.New("not expect procedure")
	}
	return nil
}
func (d *DoInstance) SetCTSpecialDnnChargingStatus(session *dbadpater.DbSessionInfo) {
	if d.DnnConfig().SpecialDnn {
		// 读取CDFFUNCPARA的数据
		result, err := omcmcfg.MmlCfgCache().Query(d.GetOmcmCfger(), omcmcfg.NameCdfFuncPara, nil)
		if err != nil {
			nflog.AgfLogger().ErrorNfLog("query CDFFUNCPARA error %s", err.Error())
			return
		}

		param, ok := result.(*cmcdf.CDFFUNCPARA)
		if !ok {
			d.GetLogger().Error("query CDFFUNCPARA result is not *cmcdf.CDFFUNCPARA")
			return
		}

		// 电信场景下话单携带特殊DNN且CDFFUNCPARA的SPECDNNSWITCH置为true用于分拣至特殊通道
		if param.SPECDNNSWITCH == cmcdf.CDFCOMMONSWITCH_TYPEENABLE {
			session.ChargingStatus = agf.ChargingStatus_SPECIALDNN
		}
	}
}

