func NewArena(def *ArenaDef) *Arena {
	if def.NumPerPool == 0 || def.NewPoolCbk == nil {
		return nil
	}

	a := &Arena{
		name:       def.Name,
		numPerPool: def.NumPerPool,
		newPoolCbk: def.NewPoolCbk,
	}

	if def.DelayReuse {
		a.delayQueue = newDelayQueue(&delayQueueDef{
			def.QueueLength,
			a.dequeueNotify,
			def.DelayTime,
			def.TimerInterval,
		})

		if a.delayQueue == nil {
			return nil
		}
	}

	return a
}
func (a *Arena) Alloc() ObjectPtr {
	a.stat.arenaAllocCnt++

	o := a.allocParallel()
	if o != nil {
		return o
	}

	// 小概率到这里。缓存的pool用完了
	o = a.allocSerial()
	if o == nil {
		a.stat.arenaAllocSerialFailed++
	}
	return o
}

