func (a *Arena) allocSerial() ObjectPtr {
	// 用写锁
	a.Lock()

	// 走到这里，说明allocParallel申请失败了，可能freePoolCache变满了，更新其free flag
	p := a.getFreePoolCache()
	a.updFreeFlag(p)

	// 再选一个空闲的pool
	a.updFreePoolCache()

	var o ObjectPtr
	p = a.getFreePoolCache()
	if p != nil {
		o = p.alloc()
	} else {
		// pool都满了就创建一个
		p = a.allocPool()
		o = p.alloc()
	}
	a.Unlock()

	return o
}
