func (d *AgfDo) directivesCtx(ctx actor.Context) error {
	switch ctx.Message().(type) {
	case *actor.Started:
		if err := d.started(ctx); err != nil {
			nflog.AgfLogger().ErrorNfLog("AgfDo started failed! err=%v", err)
			utils.Suicide(utils.FaultCode{Code: int(gconst.StartFailed), Reason: "Do Startup Failure", ServiceType: int(meta.AgfExecSvcValue)})
