	case *actor.Stopping:
		d.stopping(ctx)
	case *actor.Stopped:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "AgfDo Stopped:%+v.\n", ctx.Self())
	case *actor.Restart:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "AgfDo Restart:%+v.\n", ctx.Self())
	case *actor.Restarting:
		d.restarting(ctx)
	case *actor.Terminated:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "AgfDo received terminated massage")
	default:
		return errNotDirectivesCtx
	}
