		d.handleOmCmMsg(ctx, msg)
	case *sdrmsg.MsgStructV2:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "===== do receive a sdr message. =====")
	case transdsl.Event:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "domain object receive an event message. =====")
		if err := d.scheduler.Schedule(msg); err != nil {
			nflog.AgfLogger().ErrorNfLog("refactor procedure execute failed!")
		}
	case *ddf.ResponseMessage:
		// ignore *ddf.ResponseMessage
		nflog.AgfLogger().WriteNfLog(nflog.Info, "domain object receive ddf.ResponseMessage message. =====")
	default:
