	case *nchf.ChargingDataRefCreateParameters:
		rsp := &nchf.ChargingDataRefCreateResponses{}
		rsp.SetStatusCode(err.HttpStatusCode())
		rsp.SetProblemDetails(problemDetail)
		response.Body = rsp
	case *nchf.ChargingDataCreateParameters:
		rsp := &nchf.ChargingDataCreateResponses{}
		rsp.SetStatusCode(err.HttpStatusCode())
		rsp.SetProblemDetails(problemDetail)
		response.Body = rsp
	default:
		nflog.AgfLogger().WriteNfLog(nflog.Info, "unknown request type, not construct response")
	}
}
func (d *AgfDomainSet) agfFlowCtrl(sdrMsg *sdrmsg.MsgStructV2) bool {
	if atomic.LoadUint32(&watcher.AgfFlowCtrlSwitch) == uint32(0) ||
		softpara.Ncg().DwValueOf(softpara.AgfFlowCtrlKey) == softpara.CloseAgfFlowCtrl {
		return false
	}
	req := chgmsg.GetHttpMsgFromSdrMsg(sdrMsg)
	if !chgmsg.IsChargingCreateOrUpdateReqMsg(req) {
		return false
	}
	var rsp *httpmsg.Message
	var isFailureChgReq bool
	if isFailureChgReq = chgmsg.IsFailureChgDataReq(req); isFailureChgReq {
		rsp = chgmsg.HttpErrRspOf(req, gconst.HttpCode429TooManyRequests, "AGF enter flow ctrl status")
	} else {
		rsp = chgmsg.HttpErrRspOf(req, gconst.HttpCode503ServiceUnavailable, "AGF enter flow ctrl status")
	}
	if err := d.SendHttpResponseMsg(req.Header, rsp); err != nil {
		d.ErrorNfLog("Send Agf Flow Ctrl response error, %v.", err)
		return false
	}
	d.addPerfForAgfFc(req, isFailureChgReq)
	d.WriteNfLog(nflog.Info, "Agf flow ctrl success")
	return true
}

