func (f *fcContext) tryLog(logger unclog.Logger) bool {
	atomic.AddUint64(&f.callNum, 1)
	now := time.Now().Unix()
	switchTime := atomic.LoadInt64(&f.switchTime)
	callNum := atomic.LoadUint64(&f.callNum)
	curInterval := atomic.LoadInt32(&f.interval)
	// 每5s切换一次状态
	if now > switchTime {
		if f.trySwitchInterval(curInterval, callNum) {
			logger.Critical("Log flow ctrl interval switch to %d, last 5s log num is %d", atomic.LoadInt32(&f.interval),
				callNum)
		}
		// 更新下一次尝试切换的时间
		atomic.CompareAndSwapInt64(&f.switchTime, switchTime, now+switchPeriodSec)
		// 每5秒需要重置计数
		atomic.StoreUint64(&f.callNum, 0)
	}
	return f.shouldLog(callNum)
}
func (f *fcContext) trySwitchInterval(curInterval int32, callNum uint64) bool {
	numPerSec := callNum / switchPeriodSec
	interval := int32(1)
	// 当日志打印速率大于300条/s时，限制速率为最大300条/s
	if numPerSec > maxLogSpeedSec {
		interval = int32(numPerSec / maxLogSpeedSec)
	}
	if interval == curInterval {
		return false
	}
	return atomic.CompareAndSwapInt32(&f.interval, curInterval, interval)
}

