func (p *perfCache) reportMetricsSpecifiedOcs(reporter public.PerfReporter) {
	p.metricsSpecifiedOcsMap.Range(func(key, value interface{}) bool {
		ocsId, ok := key.(string)
		if !ok {
			nflog.AgfLogger().ErrorNfLog("ReportSpecifiedOcs failed, key is not string")
			return false
		}
		perfsSpecifiedOcs, ok := value.(perfs)
		if !ok {
			nflog.AgfLogger().ErrorNfLog("ReportSpecifiedOcs failed, value is not perfs")
			return false
		}
		for metricType, metric := range perfsSpecifiedOcs.metrics {
			val := *metric
			// 如果值为0则不调用ReportPerf，减少不必要的开销
			if val == 0 {
				continue
			}
			metricId := perfSpecifiedOcsInfo[SpecifiedOcsPerfType(metricType)]
			err := reporter.PerfEntityDirect(uint32(metricId), ocsId, val, public.PerfOpAdd)
			if err != nil {
				nflog.AgfLogger().WriteNfLog(nflog.Warning, "[addAtomPerf]: perfsSpecifiedOcs operate fail, MetricID[%d], "+
					"SpecifiedOcsPerfType[%d], objID[%s]", metricId, metricType, ocsId)
			}
			nflog.AgfLogger().WriteNfLog(nflog.Debug, "[addAtomPerf]: perfsSpecifiedOcs operate success, MetricID[%d], "+
				"SpecifiedOcsPerfType[%d], value[%d], objID[%s]", metricId, metricType, val, ocsId)
			// 话统打点后需要减少已打点的值，不能直接赋值为0，因为在上报过程中可能有打点出现
			atomic.AddUint64(metric, -val)
		}
		return true
	})
}
