	if perfReporter == nil {
		nflog.AgfLogger().WriteNfLog(nflog.Warning, "[addAtomPerf]: PerfReporter is nil, MetricID[%d], PerfCauseType[%d], objID[%s]",
			metricID, perfCauseType, public.PerfMoiIdAGFWholeSystem)
		return
	}
	if metricID == InvalidMetricID {
		return
	}

	err := perfReporter.PerfEntityDirect(uint32(metricID), public.PerfMoiIdAGFWholeSystem, value, perfOp)
	if err != nil {
		nflog.AgfLogger().WriteNfLog(nflog.Warning, "[addAtomPerf]: perfAdd operate fail, MetricID[%d], PerfCauseType[%d], objID[%s]",
			metricID, perfCauseType, public.PerfMoiIdAGFWholeSystem)
		return
	}
	nflog.AgfLogger().WriteNfLog(nflog.Debug, "[addAtomPerf]: perfAdd operate success, MetricID[%d], PerfCauseType[%d], value[%d], objID[%s]",
		metricID, perfCauseType, value, public.PerfMoiIdAGFWholeSystem)

	// pod级话统指标对应的周期累加的原子指标上报
	if _, ok := podPerfMapAdd[metricID]; ok {
		err = perfReporter.PerfMultiDim(uint32(metricID), rmf.MultiDimScan, public.PerfMoiIdAGFWholeSystem, value, perfOp)
		if err != nil {
			nflog.AgfLogger().WriteNfLog(nflog.Warning, "specified pod report fail, MetricID[%d], err:%s", metricID, err.Error())
			return
		}
		nflog.AgfLogger().WriteNfLog(nflog.Debug, "specified pod report success, MetricID[%d], value[%d], perfOp[%d]",
