	case public.PerfOpAdd:
		metricID = perfAddTypeInfo[perfCauseType]
	case public.PerfOpSet:
		metricID = perfSetTypeInfo[perfCauseType]
	default:
		metricID = InvalidMetricID
	}
	return metricID
}
