func (q *queueImpl) expand() error {
	originLen := uint32(len(q.buffer))
	if originLen >= maxSize {
		return ErrExpandFail
	}

	var newLen uint32
	if originLen <= maxSize/resizeFactor {
		newLen = originLen * resizeFactor
	} else {
		newLen = maxSize
	}
	newBuff := make([]uint32, newLen, newLen)

	for i := uint32(0); i < originLen; i++ {
		buffIndex := (q.tail + i) % originLen
		newBuff[i] = q.buffer[buffIndex]
	}

	// set the new buffer and reset head and tail
	q.buffer = newBuff
	q.head = 0
	q.tail = originLen

	return nil
}
func (q *queueImpl) Capacity() uint32 {
	return q.len
}
func (q *queueImpl) Empty() bool {
	return q.len == 0
}
func (q *queueImpl) PopFront() (uint32, bool) {
	if q.Empty() {
		return 0, false
	}
	q.head = (q.head + 1) % uint32(len(q.buffer))
	res := q.buffer[q.head]
	q.buffer[q.head] = 0
	q.len--
	return res, true
}

