func (o *obj) queryOldRecords(arg args, tableName string) map[[maxPrimaryIndexNum]interface{}]role.DdfEntry {
	records := make(map[[maxPrimaryIndexNum]interface{}]role.DdfEntry, 0)
	if !arg.earlyNrfReq {
		return records
	}

	logapi.Info("earlyNrfReq and need to delete old record")
	filter := InsIdFilterMap[tableName]
	if filter == nil {
		logapi.Error("table[%v] has no insIdFilter", tableName)
		return records
	}

	recordItf, err := o.queryAll(tableName, filter(arg.nfIdValue))
	if err != nil || recordItf == nil {
		logapi.Error("err[%v] is not nil or recordItf is nil", err)
		return records
	}

	kind := reflect.TypeOf(recordItf).Kind()
	if kind != reflect.Slice {
		return records
	}

	recordItfValue := reflect.ValueOf(recordItf)
	for i := 0; i < recordItfValue.Len(); i++ {
		valueItf := recordItfValue.Index(i).Interface()
		record := o.getDdfEntryByRecordItf(valueItf, tableName)
		if record == nil {
			continue
		}

		index := 0
		var recordPrimaryInfo [maxPrimaryIndexNum]interface{}
		for _, condition := range record.GetPrimaryFilter().Conditions {
			if index >= maxPrimaryIndexNum {
				break
			}
			recordPrimaryInfo[index] = condition.Value
			index++
		}
		records[recordPrimaryInfo] = record
	}
	return records
}
