func sendLnkLbPolicy() {
	if isReachMaxSendCountPerSec() {
		acslog.Info("deQueTimes:[%v], plySendCount:[%v], deQueNum:[%v], deQueNumPerSec:[%v]",
			deQueTimes, plySendCount, deQueNum, deQueNumPerSec)
		return
	}
	acslog.Debug("sendLnkLbPolicy to cslb lb patchPlySendCount:[%v], queuelen:[%v], capacity:[%v]",
		plySendCount, lbQueue.length, lbQueue.capacity)
	for sendLbMsgNum := 0; sendLbMsgNum < deQueNum; sendLbMsgNum++ {
		if lbQueue.length != 0 {
			lbData := lbQueue.deQueue()
			plySendCount++
			lbType := lbData.lbType
			lbMsg := lbData.lbMsg
			sendPolicy(lbType, lbMsg)
		} else {
			break
		}
	}
}
func sendHLBHashLbPly(plyCfg interface{}) {
	if cfg, ok := plyCfg.(*HlbHashPlyCfg); ok {
		if cfg == nil {
			acslog.Error("cfg is nil")
			return
		}

		ip, ipMask := Ip2uint8s(cfg.IP)
		if ip == nil && ipMask == nil {
			acslog.Error("convert ip[%v] failed", cfg.IP)
			return
		}

		hashCfg := lnkPlyCfg{
			localIp:     ip,
			localIpMask: ipMask,
			localPort:   cfg.Port,
			ipVer:       cfg.IPVer,
			tokenId:     sdrapi.InvalidToken,
			oprType:     cfg.OprType,
			seqId:       cfg.SeqId,
			inst:        sdrapi.InstHlb,
			protocolNo:  sdrapi.TcpProtocolNo,
		}
		// Port为0表示无效的三元组策略，用于下发tcp的hash下一跳组。在四元组（三元组+syn）匹配不中时，进入该下一跳，选择一个TCP给对端回RST
		if cfg.Port == 0 {
			sendHlbHashPlyWithoutSyn(&hashCfg)
		} else {
			sendHlbHashLbPlyWithSyn(&hashCfg)
		}
	}
}
func sendHlbHashLbPlyWithSyn(hashCfg *lnkPlyCfg) {
	acslog.Info("hlb hash cfg [%+v]", hashCfg)

	lbMsg := createHlbHashPolicyMsg(*hashCfg)
	if lbMsg == nil {
		acslog.Error("create actorMsg failed")
		return
	}
	err := sdrapi.SendMsg(lbMsg)
	if err != nil {
		acslog.Error("send hlb srv LbPly failed [%v]", err)
		return
	}
	// 策略话统转发打点
	perf.MetricIncrease(perf.ForWardPolicyMsgNum, perf.MetricSubmitCache)
}
func sendHlbHashPlyWithoutSyn(hashCfg *lnkPlyCfg) {
	acslog.Info("hlb hash cfg [%+v]", hashCfg)
	hashCfg.seqId += sdrapi.PlySeqIdGap // 不带syn的纯三元组策略比带syn的seqId固定多1000

	lbMsg := createHlbHashPolicyMsg(*hashCfg)
	if lbMsg == nil {
		acslog.Error("create actorMsg failed")
		return
	}
	err := sdrapi.SendMsg(lbMsg)
	if err != nil {
		acslog.Error("send hlb srv LbPly failed [%v]", err)
		return
	}
	// 策略话统转发打点
	perf.MetricIncrease(perf.ForWardPolicyMsgNum, perf.MetricSubmitCache)
	hashCfg.seqId -= sdrapi.PlySeqIdGap // 数据恢复, 避免后续开发者犯错
}
func sendHlbVpnPly(plyCfg interface{}) {
	if cfg, ok := plyCfg.(*VpnPlyCfg); ok {
		// 删除VPN的策略不进行处理
		if cfg.OprType == outermsg.OprType_OprTypeDelete {
