func (o *RspAnalyser) getReqStatusMap() (map[rgInfo]reqStatus, upfIdInfo) {
	var reqMsgMap = make(map[rgInfo]reqStatus, defaultMapLen)
	var upfIdMap = make(map[string]int, defaultMapLen)
	var upfIdInfoTmp = upfIdInfo{hasSingleUpfId: false}
	reqStatusTmp := reqStatus{}
	rg := rgInfo{}
	ratingGroups := o.GetRecvReqHttpContext().RecvReqRatingGroup()
	upfIds := o.GetRecvReqHttpContext().RecvReqUpfId()
	reqUnitFlags := o.GetRecvReqHttpContext().RecvReqRequestedUnitFlag()
	for num, ratingGroup := range ratingGroups {
		rg.RgId = ratingGroup
		rg.UpfId = upfIds[num]
		upfIdInfoTmp.upfIdTmp = upfIds[num]
		reqStatusTmp.hasRsu = reqUnitFlags[num]
		reqMsgMap[rg] = reqStatusTmp
		upfIdMap[upfIds[num]] = num
	}
	if len(upfIdMap) == singleUpfId {
		upfIdInfoTmp.hasSingleUpfId = true
	}
	return reqMsgMap, upfIdInfoTmp
}
func (o *RspAnalyser) getRspStatusMap(upfIdInfo upfIdInfo) map[rgInfo]rspStatus {
	var rspMspMap = make(map[rgInfo]rspStatus, defaultMapLen)
	rspStatusTmp := rspStatus{}
	rg := rgInfo{}
	ratingGroups := o.GetRecvRspHttpContext().RecvRspRatingGroup()
	upfIds := o.GetRecvRspHttpContext().RecvRspUpfId()
	grantedUnitFlags := o.GetRecvRspHttpContext().RecvRspGrantedUnitFlag()
	resultCodeFlags := o.GetRecvRspHttpContext().RecvRspResultCodeFlag()
	for num, ratingGroup := range ratingGroups {
		rg.RgId = ratingGroup
		rg.UpfId = upfIds[num]
		rspStatusTmp.hasGsu = grantedUnitFlags[num]
		rspStatusTmp.hasRgResultCode = resultCodeFlags[num]
		if upfIdInfo.hasSingleUpfId {
			rg.UpfId = upfIdInfo.upfIdTmp
		}
		rspMspMap[rg] = rspStatusTmp
	}
	return rspMspMap
}
func (o *RspAnalyser) procStatusMap(reqMsgMap map[rgInfo]reqStatus, rspMspMap map[rgInfo]rspStatus) {
	var errorReport int32
	for rg, reqStatus := range reqMsgMap {
		rspStatus, ok := rspMspMap[rg]
		if !ok {
			errorReport |= int32(1) << moveLeft1Bit
			continue
		}
		if !rspStatus.hasRgResultCode {
			errorReport |= int32(1) << moveLeft2Bit
		}
		if reqStatus.hasRsu && !rspStatus.hasGsu {
			errorReport |= int32(1) << moveLeft3Bit
		}
	}
	o.ocsErrReport(errorReport)
}
func (o *RspAnalyser) ocsErrReport(errorReport int32) {
	if errorReport&(int32(1)<<moveLeft1Bit) != 0 {
		o.GetErrStackLogger().PrintErrorStackWith(gconst.OcsRspMissingRgOrUpfId,
			o.GetRecvRspHttpContext().RecvRspStatusCode(), o.GetRecvRspHttpContext().RecvRspDetail())
	}
	if errorReport&(int32(1)<<moveLeft2Bit) != 0 {
		o.GetErrStackLogger().PrintErrorStackWith(gconst.OcsRspMissingRgResultCode,
			o.GetRecvRspHttpContext().RecvRspStatusCode(), o.GetRecvRspHttpContext().RecvRspDetail())
	}
	if errorReport&(int32(1)<<moveLeft3Bit) != 0 {
		o.GetErrStackLogger().PrintErrorStackWith(gconst.OcsMissingRgGsu,
			o.GetRecvRspHttpContext().RecvRspStatusCode(), o.GetRecvRspHttpContext().RecvRspDetail())
	}
}
func (o *RspAnalyser) processCreateRspLocation() error {
	const method = "processCreateRspLocation"
	if err := o.modifyCreateParametersLocation(); err != nil {
		nfErr := nferr.Wrap(err, gconst.AgfDo, method, "modifyCreateParametersLocation failed")
		return nfErr
	}

	// 如果location中未携带chargingDataRef，则需要判断是否需要NCG
	if !o.isCreateRspHasLegalLocation() {
		o.GetLogger().Info("OCS has illegal createRsp chargingDataRef")
		o.fullingCreateRspLocation()
	}
	return nil
}

