func (s *ChgMsgMetric) Reset() {
	if s.TotalReportNum < MaxSessionReportNum {
		return
	}

	s.TotalReportNum = 0
	element := reflect.ValueOf(s).Elem()
	for i := 0; i < element.NumField(); i++ {
		fieldName := element.Type().Field(i).Name
		// 会话数统计不清空
		if !strings.Contains(fieldName, "SessionNum") {
			element.Field(i).SetInt(0)
		}
	}
}
func (s *ChgMsgMetric) Report() string {
	if !IsChgMsgMetricInUse() {
		return "ChgMsg Metric function is close.\n"
	}
	s.TotalReportNum.Inc()
	tableStr := &strings.Builder{}
	table := NewWriter(tableStr)
	table.SetHeader("ChgMsg Metric")

	// 设置表格数据
	table = s.setSessionInfo(table)

	table = s.set5GTableInfo(table)

	table = s.set4GTableInfo(table)

	// 输出表格数据
	table.Render()
	return tableStr.String()
}
func getChgMsgMetricPercent(num Metric, total Metric) string {
	if total == 0 {
		return "0"
	}
	value := num * Percent / total
	return value.StrOfVal()
