	p := newPool(id, a.numPerPool, a.newPoolCbk(a.numPerPool), &a.stat)
	if p == nil {
		return nil
	}
	idx := a.convertIdToIdx(id)
	// 对allocId时申请的空间进行赋值
	a.pools[idx] = p
	a.setFreePoolCache(p)
	a.updFreeFlag(p)
	return p
}
func (a *Arena) convertIdxToId(idx int) uint16 {
	// 0是非法值
	return uint16(idx + 1)
}
func (a *Arena) convertIdToIdx(id uint16) int {
	return int(id - 1)
}
func (a *Arena) isIdxValid(idx int) bool {
