func (a *routeActor) setRoutePolicy() {
	acslog.Info("enter setRoutePolicy")

	if !localpolicy.IsLocalPolicyOk() {
		acslog.Error("local policy is not ok")
		return
	}

	for appid, routeInfo := range route.Configs {
		if policyok, ok := routePolicyOk[appid]; ok && !policyok {
			acslog.Error("set app [%v] route policy begin", appid)

			version := sdrapi.GetRandomVersion()
			routePolicyVersion.Store(appid, version)

			routePly, err := createAppRoutePly(appid, routeInfo, version)
			if err != nil {
				acslog.Error("create app route policy failed, err: %+v", err)
				return
			}
			sErr := sdrapi.SendMsg(routePly)
			if sErr != nil {
