func (qu *QueryUtil) checkNotifyTypeParam(profileTbl *ddftbl.CachedPnfProfile, serviceTbl *ddftbl.CachedPnfService) bool {
	// 如果不指定notificationType查询，无需填充callbackUri，也无需根据该条件过滤。
	if len(qu.getQueryDefaultNotificationType()) == 0 {
		return true
	}
	if qu.matchDefaultNotification(profileTbl.DefaultNotificationSubscriptions) {
		return true
	}
	return qu.matchDefaultNotification(serviceTbl.DefaultNotificationSubscriptions)
}

func (qu *QueryUtil) matchDefaultNotification(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription) bool {
	if len(qu.getQueryDefaultNotificationType()) == 0 {
		return true
	}
	// 如果cache中的没有defaultNotificationSubs，则认为该profile/service是不匹配的
	if len(defaultNotificationSubs) == 0 {
		return false
	}
	switch qu.getQueryDefaultNotificationType() {
	case nnrf29510.N1Messages:
		return checkN1Class(defaultNotificationSubs, qu.getCacheQueryMsg())
	case nnrf29510.N2Information:
		return checkN2Class(defaultNotificationSubs, qu.getCacheQueryMsg())
	default:
		return checkOtherType(defaultNotificationSubs, qu.getCacheQueryMsg())
	}
}

func checkN2Class(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
			continue
		}
		if queryMsg.N2InfoClass == defaultNotificationSubs[idx].N2InformationClass {
			return true
		}
	}
	return false
}

func checkN1Class(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
			continue
		}
		if queryMsg.N1MsgClass == defaultNotificationSubs[idx].N1MessageClass {
			return true
		}
	}
	return false
}

func checkOtherType(defaultNotificationSubs []nnrf29510.DefaultNotificationSubscription, queryMsg *cachemsg.CacheQueryMsg) bool {
	if queryMsg == nil {
		logapi.Error("msg is null")
		return false
	}
	for idx := range defaultNotificationSubs {
		if queryMsg.NotificationType != defaultNotificationSubs[idx].NotificationType {
			continue
		}
		return true
	}
	return false
}

func (qu *QueryUtil) checkAmfHotSpare(recordTime int64) bool {
	if len(qu.Param.Msg.GetGuami()) != 0 && (qu.currentTime-recordTime) > int64(common.ThreeHours) {
		return true
	}
	return false
}

func (qu *QueryUtil) checkMainAmfInfo(amfTimeout bool) bool {
	if amfTimeout && qu.getCachedMainAmInfo(qu.Param.Msg.GetGuami()) == nil {
		return true
	}
	return false
}

// queryNfService 查询service
func (qu *QueryUtil) queryNfService(profileTbls []*ddftbl.CachedPnfProfile, instIdMap map[uint32]string) ([]*cachemsg.NrfService, map[uint32]uint32, QueryRet) {
	serviceList := make([]*cachemsg.NrfService, 0, 0)
	invalidProfileInstanceIds := make(map[uint32]uint32, 0)

	foundService := false
	amfTimeout := false
	for _, profileTbl := range profileTbls {
		serviceTbls := qu.queryNfServiceWithProfileTbl(profileTbl)
		insId := nfidmapmgmt.GetInstanceIdByValue(profileTbl.NfInstanceId)
		instIdMap[profileTbl.NfInstanceId] = insId

		isProfileValid := false
		for _, serviceTbl := range serviceTbls {
			if !qu.IsTargetService(serviceTbl) {
				logapi.Info("queryNfService service invalid SrvInstanceId[%v]!", serviceTbl.SrvInstanceId)
				continue
			}
			if !qu.checkNotifyTypeParam(profileTbl, serviceTbl) {
				logapi.Info("queryNfService service default notification class not match. [instance id:%s]!", serviceTbl.SrvInstanceId)
				continue
			}
			isProfileValid = true
			foundService = true
			serviceList = append(serviceList, qu.getRegService(insId, profileTbl, serviceTbl)...)
		}

		amfTimeout = qu.checkAmfHotSpare(profileTbl.RecordTime)

		// 默认通知消息路由查询时如果profile的信息不匹配，并且该profile下的所有service的信息也不匹配，需要将该profile从结果剔除
		if !isProfileValid && !qu.matchDefaultNotification(profileTbl.DefaultNotificationSubscriptions) {
			invalidProfileInstanceIds[profileTbl.NfInstanceId] = 1
		}
	}

	if !foundService {
		logapi.Info("find nf service fail! QueryNotFound")
		return serviceList, invalidProfileInstanceIds, QueryNotFound
	}

	if len(serviceList) == 0 {
		logapi.Info("find nf service fail! QueryStatusUnavailable")
		return serviceList, invalidProfileInstanceIds, QueryStatusUnavailable
	}

	logapi.Info("find nf service success!")
	if qu.checkMainAmfInfo(amfTimeout) {
		return serviceList, invalidProfileInstanceIds, QueryResultCanBeUse
	}
	return serviceList, invalidProfileInstanceIds, QueryFoundSucc
}


