func (p *primIdx) insert(rec IntervalRec) error {
	var extraKey interval.ExtraKey
	if p.primaryKeyType == interval.PrimaryKeyTypeWithExtraKey {
		extraKeyGetter, ok := rec.(interval.ExtraKeyGetter)
		if !ok {
			return ErrNoExtraKey
		}
		extraKey = extraKeyGetter.GetExtraKey()
	}

	var err error
	p.Lock()
	defer p.Unlock()
	inst := p.idx[rec.GetInstId()]
	if inst == nil {
		inst = make(map[uint64]*recNode, numPerNf)
		p.idx[rec.GetInstId()] = inst
	}

	head := inst[rec.GetStart()]
	for cur := head; cur != nil; cur = cur.next {
		// 判断号段表Start、End、isExtraKeyEqual一致标识记录已存在，不需要插入
		if cur.rec.GetEnd() == rec.GetEnd() && p.isExtraKeyEqual(cur.rec, extraKey) {
			err = ErrRecordExist
			break
		}
	}

	if err == nil {
		if inertErr := p.insertNew(rec, head, inst); inertErr != nil {
			return inertErr
		}
	}
	return err
}
func (p *primIdx) insertNew(rec IntervalRec, head *recNode, inst map[uint64]*recNode) error {
	n := p.mallocNode()
	if n == nil {
		return ErrMallocFailed
	}
	n.rec = rec
	if head == nil {
		inst[rec.GetStart()] = n
	} else {
		n.next = head.next
		head.next = n
	}
	return nil
}
