	n := len(p.idx[instId])
	p.RUnlock()
	return n != 0
}
func (p *primIdx) queryByPrimaryKey(key interval.PrimaryKey) IntervalRec {
	var result IntervalRec
	p.RLock()
	inst := p.idx[key.NfId]
	if inst == nil {
		p.RUnlock()
		return nil
	}
	for cur := inst[key.Start]; cur != nil; cur = cur.next {
		if cur.rec.GetEnd() == key.End && p.isExtraKeyEqual(cur.rec, key.ExtraKey) {
			result = cur.rec
			break
		}
	}
	p.RUnlock()
	return result
}

