func (d *doActorManagerImpl) MsgDispatch(msg *sdrmsg.MsgStructV2) (DoActor, *innermsg.MsgFromDS, error) {
	ds2DoMsg := dstodomsg.ConvertSdrMsg2Ds2DoMsg(msg, d.domainToken)
	if ds2DoMsg == nil {
		nfErr := nferr.New("doActorManagerImpl", "MsgDispatch", "agf ds received invalid sdr msg:%v", msg)
		nflog.AgfLogger().ErrorNfLog("Convert sdr msg to Ds2DoMsg failed.")
		return nil, nil, nfErr
	}

	msgFromDs := &innermsg.MsgFromDS{ServiceMsg: transdsl.NewEvent(ds2DoMsg.GetEventId(), ds2DoMsg), Token: d.domainToken}
	// Ds接收到该消息的时间赋值
	msgFromDs.ProcessStartTimestamp = uint64(time.Now().UnixNano() / int64(time.Millisecond))
	switch ds2DoMsg.(type) {
	case *dstodomsg.Ds2DoChargingCreateReqParameters, *dstodomsg.Ds2DoChargingCreateRefReqParameters,
		*dstodomsg.Ds2DoChargingUpdateReqParameters, *dstodomsg.Ds2DoChargingReleaseReqParameters:
		d.doIndex++
		domainObj, err := d.AllocDoActor(d.doIndex)
		msgFromDs.DoIndex = d.doIndex
		if isDomainObjInvalid(domainObj, err) {
			return nil, msgFromDs, err
		}
		nflog.AgfLogger().WriteNfLog(nflog.Info, "current I/U/T req alloc doIndex is %d.", d.doIndex)
		return domainObj, msgFromDs, nil
	case *dstodomsg.Ds2DoChargingNotifyReqParameters, *dstodomsg.Ds2DoCdfAlmNotifyReq:
		d.doIndex++
		domainObj, err := d.AllocDoActor(d.doIndex)
		if isDomainObjInvalid(domainObj, err) {
			return nil, msgFromDs, err
		}

		nflog.AgfLogger().WriteNfLog(nflog.Info, "current notify type msg alloc doIndex is %d.", d.doIndex)
		msgFromDs.DoIndex = d.doIndex
		return domainObj, msgFromDs, nil
	default:
		domainObj, err := d.dispatchRspMsg(msg.DestKey.KeyValue, msgFromDs)
		if isDomainObjInvalid(domainObj, err) {
			nflog.AgfLogger().WriteNfLog(nflog.Info, "Dispatch rsp failed: %s, msg is %v.", err.Error(), msg.PayLoad)
