func (s *subscribe) updateServerUrl(msg cse.CseServiceNotifyItf) {
	serNotify := getServiceNotifyInfo(msg)
	s.WriteLog(log.Info, "cdrws: get service info from notification msg successfully, serviceInfo: %+v", serNotify)
	if cse.ActionDelete == serNotify.NotifyAction {
		s.procDeleteNotify(serNotify.SerName, serNotify.InstanceId)
		return
	}
	NewServiceManager().AddServiceInsStat(serNotify.SerName, serNotify.InstanceId, serNotify.InsStatus)
	serverUrl := ""
	for _, endPoint := range serNotify.EndPoints {
		s.WriteLog(log.Info, "cdrws: serviceName %s, endPoint: %s", serNotify.SerName, endPoint)
		serverUrl = strings.Replace(endPoint, constHighWayPrefix, constHttpPrefix, 1)
		break
	}
	if "" == serverUrl {
		s.WriteLog(log.Error, "cdrws: failed to get service(%s) info", serNotify.SerName)
		NewServiceManager().OmgSrv.SetQueryServiceFlag(true)
		s.GetServiceInfo(serNotify.SerName)
		return
	}
	if !s.IsNeedRetrySub(serNotify, serverUrl) {
		return
	}
	if cse.ActionUpdate == serNotify.NotifyAction || serNotify.InsStatus == ConstSlaverSrvInsStat {
		if serNotify.InstanceId == NewServiceManager().OmgSrv.GetSubInstanceId() {
			s.setSubProc(serNotify.SerName)
