func getServiceNotifyInfo(message interface{}) CseServiceNotify {
	serNotify := CseServiceNotify{}
	switch msg := message.(type) {
	case cse.CseServiceNotifyItf:
		serNotify.NotifyAction = msg.CseGetNotifyAction()
		serNotify.SerName = msg.GetSrvName()
		serNotify.InstanceId = msg.GetInstanceID()
		serNotify.InsStatus = msg.GetStatus()
		serNotify.EndPoints = msg.GetEndpoints()
		serNotify.LabelMap = msg.GetLabelMap()
		log.Logger().WriteLog(log.Warning, "GetLabelMap: %v", msg.GetLabelMap())

	case cse.CseServiceInstanceItf:
		serNotify.SerName = msg.GetSrvName()
		serNotify.InstanceId = msg.GetInstanceID()
		serNotify.InsStatus = msg.GetStatus()
		serNotify.EndPoints = msg.GetEndpoints()
		serNotify.LabelMap = msg.GetLabelMap()
	default:
		log.Logger().WriteLog(log.Error, "cdrws: unknown message %T", msg)
	}
	return serNotify
}
func (s *subscribe) procDeleteNotify(serName string, serInsId base.InstanceID) {
	NewServiceManager().OmgSrv.DelServerAddr(serInsId)
	NewServiceManager().OmgSrv.DelServiceInsStat(serInsId)
	subStatus := NewServiceManager().OmgSrv.GetSubStatus()
	switch subStatus {
