			NewServiceManager().OmgSrv.SetQueryServiceFlag(true)
			s.GetServiceInfo(serName)
			return
		}
	case Subscribing:
		if serInsId == NewServiceManager().OmgSrv.GetSubInstanceId() {
			s.WriteLog(log.Info, "cdrws: cell subscribe status is Subscribing,need to query service,serviceName %s", serName)
