func (e *extension) doMigration(msg *csmsg.MigrationNotify) {
	if msg.RootTokenGroup >= util.TokenGroupNum {
		/*
		* @log_type 辅助信息
		* @log_analysis 迁移通知TokenGroup大于TokenGroup上限
		* @log_suggest 检查DCF侧配置
		 */
		logapi.Error("TokenGroup too large %+v", msg)
		return
	}

	switch msg.Stage {
	case csmsg.Stage_Recovery:
		for _, item := range msg.Items {
			if item == nil {
				logapi.Error("token item is nil, msg.Items is %v", msg.Items)
				continue
			}

			root := rootKey{
				tokenGroup:  util.TokenGroup(msg.RootTokenGroup), // <16
				rootTokenID: base.RootTokenID(item.RootTokenID),
			}
			e.recovery(root, msg, item.DomainTokenID)
		}
	case csmsg.Stage_Smooth, csmsg.Stage_Recycle:
		for _, item := range msg.Items {
			if item == nil {
				continue
			}

			root := rootKey{
				tokenGroup:  util.TokenGroup(msg.RootTokenGroup), // <16
				rootTokenID: base.RootTokenID(item.RootTokenID),
			}

			e.smoothOrRecycle(root, msg)
		}
	default:
		/*
		* @log_type 疑点
		* @log_analysis 迁移通知消息携带状态未知
		* @log_suggest 检查DCF侧业务逻辑
		 */
		logapi.Error("unknown stage %v", msg.Stage)
		return
	}
}
func (e *extension) recovery(rootKey rootKey, msg *csmsg.MigrationNotify, domainTokenIDS []uint32) {
	rootToken, ok := e.rootToken[rootKey]
	if !ok {
		e.addRootToken(rootKey, msg, domainTokenIDS)
		return
	}

	switch {
	case rootToken.stage == csmsg.Stage_Recovery:
		if int(rootToken.finishCount) == len(rootToken.domainToken) {
			e.migrationResult(rootToken)
			/*
			* @log_type 辅助信息
			* @log_analysis 重复消息，controller没收到回应，或dcf短时间内多次下发迁移通知。
			* @log_suggest token已存在，非问题
			 */
			logapi.Warning("recovery: repeat msg[%v], transId[%v]", rootKey, msg.TransId)
			rootToken.transId = msg.TransId
			rootToken.appCtrlInstanceId = msg.AppCtrlInstanceId
			e.sendMigrationRspToAppCtrl(rootToken)
		} else {
			e.fixRootToken(rootToken)
			/*
			* @log_type 问题
			* @log_analysis 未收到ds的token迁移回执导致重试发送token迁移通知，长时间打印可能伴随进程故障告警出现
			* @log_suggest 如果长时间打印，请过滤日志关键字"ddf:",检查是否有长时间打印如下日志之一,有的话请联系ddf定位：
			* "make ask pub end","plugin link connect task send","mng connect task","router can not get cn"
			* ddf没有以上日志的话请联系业务机制appctrl定位。
			 */
			logapi.Error("recovery: repeat msg,not end , %v", rootKey)
		}
	case rootToken.smoothFlag == csmsg.SmoothFlag_Dst:
		e.migrationResultNoWait(rootKey, csmsg.Stage_Recovery, csmsg.SmoothFlag_Nil)
		/*
		* @log_type 问题
		* @log_analysis 可能是CTRL复位后重新推送
		*               不能回smooth阶段，需要直接反填消息里内容，否则Ctrl会有问题
		* @log_suggest 检查日志是否长时间打印，若长时间打印请联系业务机制appctrl定位
		 */
		logapi.Error("recovery: repeat previous msg, %v", rootKey)
	case rootToken.smoothFlag == csmsg.SmoothFlag_Src:
		// N-WAY场景，主降备需要重启DS，但是不能删除数据特征。其他场景这样处理也不会有问题
		e.migrationResultNoWait(rootKey, csmsg.Stage_Recovery, csmsg.SmoothFlag_Nil)
		e.restartRootToken(rootToken)
		logapi.Error("recovery: maybe N-WAY, %v", rootKey)
	default:
		/*
		* @log_type 疑点
		* @log_analysis 消息附带token状态错误
		* @log_suggest 检查DCF侧业务逻辑
		 */
		logapi.Error("recovery: error msg, %v", rootKey)
	}
}
func (e *extension) smoothOrRecycle(rootKey rootKey, msg *csmsg.MigrationNotify) {
	stage := msg.Stage
	smoothFlag := msg.SmoothFlag
	rootToken, ok := e.rootToken[rootKey]
	if !ok {
		/*
		* @log_type 辅助信息
		* @log_analysis 删除发现没有token直接返回
		* @log_suggest 等待后检查
		 */
		logapi.Error("root token not found, %v", rootKey)
		if stage == csmsg.Stage_Recycle || smoothFlag == csmsg.SmoothFlag_Src {
			e.migrationResultNoWait(rootKey, stage, smoothFlag)
		}
		return
	}

	// 重复消息，Executor没回相应，Controller会重试。
	if stage == rootToken.stage && smoothFlag == rootToken.smoothFlag {
		if int(rootToken.finishCount) == len(rootToken.domainToken) {
			e.migrationResult(rootToken)
			/*
			* @log_type 辅助信息
			* @log_analysis 重复消息，controller没收到回应，或dcf短时间内多次下发迁移通知。
			* @log_suggest token已存在，非问题
			 */
			logapi.Error("repeat msg,%v", rootKey)
		}
		return
	}

	// 清除上一个阶段的数据
	rootToken.errorCount = 0
	rootToken.finishCount = 0
	rootToken.stage = stage
	rootToken.smoothFlag = smoothFlag
	rootToken.transId = msg.TransId

	for _, domainToken := range rootToken.domainToken {
		domainToken.finished = false
		if domainToken.pid != nil { // 实测存在在pid赋值之前就走到这里可能性
			notify := &cellmsg.MigrationNotify{Stage: stage, SmoothFlag: smoothFlag}
			actor.EmptyRootContext.Send(domainToken.pid, notify)
		}
	}
}
func (e *extension) addRootToken(rootKey rootKey, msg *csmsg.MigrationNotify, domainTokenIDS []uint32) {
	rootToken := &rootToken{
		rootKey:           rootKey,
		rootTokenType:     base.RootTokenType(msg.RootTokenType),
		stage:             csmsg.Stage_Recovery,
		smoothFlag:        csmsg.SmoothFlag_Nil,
		domainToken:       make([]*domainToken, len(domainTokenIDS), len(domainTokenIDS)),
		transId:           msg.TransId,
		appCtrlInstanceId: msg.AppCtrlInstanceId,
	}

	e.rootToken[rootKey] = rootToken

	par := &cell.StartActorPar{
		Actors: make([]cell.BuildActorReq, len(rootToken.domainToken), len(rootToken.domainToken)),
	}

	for i, DomainTokenID := range domainTokenIDS {
		domainKey := domainKey{
			tokenGroup:  rootKey.tokenGroup,
			domainToken: base.DomainToken(DomainTokenID),
		}

		domainToken := &domainToken{
			domainKey: domainKey,
			rootToken: rootToken,
		}

		e.domainToken[domainKey] = domainToken
		rootToken.domainToken[i] = domainToken
		if req, err := e.newBuildActorReq(rootKey, base.DomainToken(DomainTokenID)); err == nil {
			par.Actors[i] = req
		}
	}

	logapi.Error("StartActorPar %+v", par)
	e.tellToSelf(par)
}

