func (d *DoInstance) UpdateCtx(req *msg.Ds2DoReqMsg) error {
	// 如果是SMSF流程，则单独更新上下文
	// 当前SMSF有两个流程，一个消息流程，另一个是告警流程，均走该上下文更新流程
	if d.IsShortMsgProcess(req) {
		return d.UpdateSmsfCtx(req)
	}

	if req.Session == nil {
		d.SmfDisasterRecoveryHandler.SendSmfSessionNilRsp(req.Req)
		return nil
	}
	// 更新基础上下文
	d.BaseContext.Update(req.DoIndex, req.Session.SessionKey, req.Token)
	if err := d.SdrContext.Update(d.BaseContext.DoIndex(), d.BaseContext.TokenId(), req.ChgDataRef, d.BaseContext.TransId()); err != nil {
		return err
	}
	procedure := context.ChgProcedureOf(req.Req.GetBody())
	if procedure == context.InvalidProcedure {
		return errors.New("receive invalid request type")
	}
	if err := d.RecvReqHttpContext.Update(req.Req, req.ReqField); err != nil {
		return err
	}

	// 赋值接收到请求消息的开始时间，用于AGF处理时延话统统计
	d.PerfReporter.SetMsgReqStartTimeStamp(req.ProcessStartTimestamp)
	d.DoMetricReporter.GetMetricReporter().DelayMetric.ReqChgMsgFromSmf()

	//  Notify流程上下文特殊处理
	if procedure == context.NotifyProcedure {
		return d.updateNotifyContext(req)
	}

	session := d.updateChgMsgSession(req.Session, req.ReqField)
	carrier := checkCarrier(session)
	d.ChgContext.Update(session, req.LocalChgSession, procedure, carrier)
	d.OcsContext.Update(d.ChgContext.Session().CongestCtrlCtxData())
	d.CdfContext.Update(req.Duration)
	d.GetCongestionContext().Update(req.CongestSCtx)
	d.TopoContext.Update(d.GetRecvReqHttpContext().RecvReqDnnId())
	d.DoMetricReporter.AddChgMsgMetricByChgDataReq()
	d.GetLogger().Info("Procedure is " + context.ChgProcedureName[procedure])
	d.GetDoMetricReporter().ReqFromSmfMetric()

	// 根据请求信息进行话统打点
	d.PerfReporter.AddPerfByChgMsg()
	return nil
}

