func NewListWatch(resource types.Resource) *cache.ListWatch {
	listFunc := func(options metav1.ListOptions) (runtime.Object, error) {
		return ListFunc(resource, options)
	}

	watchFunc := func(options metav1.ListOptions) (watch.Interface, error) {
		return WatchFunc(resource, options)
	}

	return &cache.ListWatch{ListFunc: listFunc, WatchFunc: watchFunc}
}
func NewListWatchWithFilter(resource types.Resource, lh ListFilter, wh watch.FilterFunc) *cache.ListWatch {
	listFunc := func(options metav1.ListOptions) (runtime.Object, error) {
		obj, err := ListFunc(resource, options)
		if err != nil || lh == nil {
			return obj, err
		}
		return lh(obj), nil
	}

	watchFunc := func(options metav1.ListOptions) (watch.Interface, error) {
		w, err := WatchFunc(resource, options)
		if err != nil || wh == nil {
			return w, err
		}

		return watch.Filter(w, func(in watch.Event) (watch.Event, bool) {
			switch in.Type {
			case watch.Bookmark:
				return in, true
			default:
				return wh(in)
			}
		}), nil
	}

	return &cache.ListWatch{ListFunc: listFunc, WatchFunc: watchFunc}
}
